PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE _content_tes (id TEXT PRIMARY KEY, "title" VARCHAR, "body" TEXT, "cover" VARCHAR, "date" DATE, "description" VARCHAR, "extension" VARCHAR, "meta" TEXT, "navigation" TEXT DEFAULT true, "path" VARCHAR, "seo" TEXT DEFAULT '{}', "stem" VARCHAR, "tag" VARCHAR);
CREATE TABLE _content_search (id TEXT PRIMARY KEY, "title" VARCHAR, "body" TEXT, "description" VARCHAR, "extension" VARCHAR, "meta" TEXT, "navigation" TEXT DEFAULT true, "path" VARCHAR, "seo" TEXT DEFAULT '{}', "stem" VARCHAR, "__hash__" TEXT UNIQUE);
CREATE TABLE _content_info (id TEXT PRIMARY KEY, "ready" BOOLEAN, "structureVersion" VARCHAR, "version" VARCHAR, "__hash__" TEXT UNIQUE);
CREATE TABLE _content_content (id TEXT PRIMARY KEY, "title" VARCHAR, "body" TEXT, "description" VARCHAR, "extension" VARCHAR, "meta" TEXT, "navigation" TEXT DEFAULT true, "path" VARCHAR, "seo" TEXT DEFAULT '{}', "stem" VARCHAR, "__hash__" TEXT UNIQUE);
CREATE TABLE _content_berita (id TEXT PRIMARY KEY, "title" VARCHAR, "body" TEXT, "date" DATE, "description" VARCHAR, "extension" VARCHAR, "meta" TEXT, "navigation" TEXT DEFAULT true, "path" VARCHAR, "seo" TEXT DEFAULT '{}', "stem" VARCHAR, "tags" TEXT, "__hash__" TEXT UNIQUE);
CREATE TABLE _content_guru (id TEXT PRIMARY KEY, "title" VARCHAR, "body" TEXT, "catatan" VARCHAR, "description" VARCHAR, "extension" VARCHAR, "foto" VARCHAR, "jabatan" VARCHAR, "kelas" VARCHAR, "lengkap" VARCHAR, "meta" TEXT, "nama" VARCHAR, "navigation" TEXT DEFAULT true, "path" VARCHAR, "pelatihan" TEXT, "pendidikan" VARCHAR, "seo" TEXT DEFAULT '{}', "sosial" TEXT NULL, "stem" VARCHAR, "__hash__" TEXT UNIQUE);
CREATE TABLE _content_artikel (id TEXT PRIMARY KEY, "title" VARCHAR, "author" VARCHAR, "body" TEXT, "date" DATE, "description" VARCHAR, "extension" VARCHAR, "image" VARCHAR, "meta" TEXT, "navigation" TEXT DEFAULT true, "path" VARCHAR, "seo" TEXT DEFAULT '{}', "stem" VARCHAR, "tags" TEXT, "__hash__" TEXT UNIQUE);
CREATE TABLE _content_kegiatan (id TEXT PRIMARY KEY, "title" VARCHAR, "body" TEXT, "cover" VARCHAR, "date" DATE, "description" VARCHAR, "extension" VARCHAR, "meta" TEXT, "navigation" TEXT DEFAULT true, "path" VARCHAR, "seo" TEXT DEFAULT '{}', "stem" VARCHAR, "tag" VARCHAR, "__hash__" TEXT UNIQUE);
CREATE TABLE _content_media (id TEXT PRIMARY KEY, "title" VARCHAR, "extension" VARCHAR, "idVideo" VARCHAR, "kelas" VARCHAR, "link" VARCHAR, "meta" TEXT, "pelajaran" VARCHAR, "stem" VARCHAR, "__hash__" TEXT UNIQUE);
