INSERT INTO "_content_tes" VALUES('tes/tes/0.kegiatan1.yml','kegiatan1','{"title":"kegiatan1","description":"This is a sample description.","cover":"https://res.cloudinary.com/dyy24w5kl/image/upload/v1732023187/artikel/artikel_sejarah_pendidikanfreepik__adorable-cartoon-style-indonesian-education-after-__62014_fye57v.jpg","date":"2023-10-05T00:00:00.000Z","tag":"fasilitas","foto":"sartijab"}','https://res.cloudinary.com/dyy24w5kl/image/upload/v1732023187/artikel/artikel_sejarah_pendidikanfreepik__adorable-cartoon-style-indonesian-education-after-__62014_fye57v.jpg','2023-10-05T00:00:00.000Z','This is a sample description.','yml','{"foto":"sartijab"}','true','/tes/kegiatan1','{"title":"kegiatan1","description":"This is a sample description."}','tes/0.kegiatan1','fasilitas');
INSERT INTO "_content_tes" VALUES('tes/tes/1.sartijab.yml','Sertijab Kepala Sekolah','{"title":"Sertijab Kepala Sekolah","description":"This is a sample description.","cover":"https://res.cloudinary.com/dyy24w5kl/image/upload/v1732023187/artikel/artikel_sejarah_pendidikanfreepik__adorable-cartoon-style-indonesian-education-after-__62014_fye57v.jpg","date":"2023-10-05T00:00:00.000Z","tag":"sertijab"}','https://res.cloudinary.com/dyy24w5kl/image/upload/v1732023187/artikel/artikel_sejarah_pendidikanfreepik__adorable-cartoon-style-indonesian-education-after-__62014_fye57v.jpg','2023-10-05T00:00:00.000Z','This is a sample description.','yml','{}','true','/tes/sartijab','{"title":"Sertijab Kepala Sekolah","description":"This is a sample description."}','tes/1.sartijab','sertijab');
INSERT INTO "_content_search" VALUES('search/artikel/1.sejarah pendidilan.md','Sejarah Pendidikan di Indonesia: Perkembangan dan Transformasi dari Masa ke Masa','{"type":"minimark","value":[["p",{},"Sejarah pendidikan di Indonesia mencakup perkembangan dari sistem tradisional hingga era modern. Artikel ini mengulas perjalanan pendidikan Indonesia dari masa kerajaan, penjajahan Belanda, pendudukan Jepang, hingga pasca kemerdekaan, serta tantangan dan harapan di masa depan."],["p",{},"Pendidikan di Indonesia memiliki perjalanan yang panjang dan penuh tantangan, dipengaruhi oleh berbagai faktor sejarah, politik, dan sosial budaya. Sejarah pendidikan di Indonesia dimulai jauh sebelum masa penjajahan, dengan sistem pendidikan tradisional yang telah ada di masyarakat. Namun, pengaruh luar, baik dari bangsa Eropa maupun penjajahan, memainkan peran yang besar dalam pembentukan sistem pendidikan seperti yang kita kenal sekarang."],["h2",{"id":"pendidikan-pada-masa-kerajaan"},"Pendidikan pada Masa Kerajaan"],["p",{},"Sebelum kedatangan bangsa Eropa, pendidikan di Indonesia lebih bersifat informal dan tradisional, mencerminkan kearifan lokal yang telah berkembang selama berabad-abad. Masyarakat adat memiliki sistem pengajaran yang unik, di mana pengetahuan diwariskan secara turun-temurun melalui proses belajar mengajar yang terintegrasi dalam kehidupan sehari-hari. Proses pembelajaran ini tidak terbatas pada ruang kelas formal, melainkan berlangsung dalam berbagai konteks sosial dan budaya, seperti di ladang, hutan, pantai, atau dalam upacara-upacara adat. Pengetahuan yang diajarkan mencakup spektrum yang luas, meliputi keterampilan praktis seperti pertanian dan perdagangan, serta aspek-aspek kehidupan yang lebih abstrak seperti seni, nilai-nilai budaya, dan ajaran agama. Metode pengajaran ini memungkinkan transfer pengetahuan yang holistik, memadukan teori dan praktik dalam satu kesatuan yang utuh."],["p",{},["img",{"alt":"New image","src":"https://res.cloudinary.com/dyy24w5kl/image/upload/v1732023188/artikel/artikel_sejarah_pendidikanfreepik__adorable-cartoon-style-education-in-the-era-of-the__62008_xe3op3.jpg"}]],["p",{},"Di kerajaan-kerajaan besar seperti Majapahit dan Sriwijaya, pendidikan memiliki posisi yang sangat penting dalam struktur sosial dan pemerintahan. Kedua kerajaan ini, yang merupakan pusat peradaban di Nusantara pada masanya, mengembangkan sistem pendidikan yang lebih terstruktur, meskipun masih bersifat eksklusif. Pendidikan agama Hindu-Buddha menjadi landasan filosofis, sementara ilmu pengetahuan dalam bidang astronomi, matematika, dan sastra dikembangkan sebagai pilar intelektual kerajaan. Astronomi digunakan untuk menentukan musim tanam dan pelayaran, matematika untuk arsitektur dan perdagangan, sementara sastra menjadi media untuk melestarikan sejarah dan nilai-nilai budaya. Pada masa ini, pendidikan formal sering kali menjadi privilese golongan bangsawan atau mereka yang berada dalam lingkup istana, menciptakan elit intelektual yang berperan penting dalam pemerintahan dan diplomasi. Meskipun demikian, pengetahuan ini tidak sepenuhnya terisolasi, karena ada mekanisme penyebaran ilmu melalui pesantren, padepokan, dan lembaga pendidikan tradisional lainnya yang lebih terbuka untuk masyarakat umum. Sistem pendidikan di kerajaan-kerajaan tersebut masih sangat terkait erat dengan kehidupan kerajaan dan budaya yang berkembang, mencerminkan kompleksitas struktur sosial dan politik pada masa itu."],["h2",{"id":"pendidikan-pada-masa-penjajahan-belanda"},"Pendidikan pada Masa Penjajahan Belanda"],["p",{},"Pada masa penjajahan Belanda, yang berlangsung dari awal abad ke-17 hingga tahun 1942, sistem pendidikan di Indonesia mengalami perubahan yang signifikan dan transformatif. Pemerintah kolonial Belanda memperkenalkan sistem pendidikan yang lebih terstruktur dan formal, menggantikan sistem pendidikan tradisional yang telah ada sebelumnya. Meskipun demikian, sistem pendidikan yang dibawa oleh Belanda ini memiliki karakteristik yang sangat diskriminatif, mencerminkan hierarki sosial dan rasial yang ada pada masa itu. Tujuan utama dari sistem pendidikan ini bukanlah untuk mencerdaskan kehidupan bangsa Indonesia, melainkan lebih ditujukan"]],"toc":{"title":"","searchDepth":2,"depth":2,"links":[{"id":"pendidikan-pada-masa-kerajaan","depth":2,"text":"Pendidikan pada Masa Kerajaan"},{"id":"pendidikan-pada-masa-penjajahan-belanda","depth":2,"text":"Pendidikan pada Masa Penjajahan Belanda"}]}}','Sejarah pendidikan di Indonesia mencakup perkembangan dari sistem tradisional hingga era modern. Artikel ini mengulas perjalanan pendidikan Indonesia dari masa kerajaan, penjajahan Belanda, pendudukan Jepang, hingga pasca kemerdekaan, serta tantangan dan harapan di masa depan.','md','{"date":"2024-11-19T00:00:00.000Z","author":"Dinar Permadi","image":"https://res.cloudinary.com/dyy24w5kl/image/upload/v1732023187/artikel/artikel_sejarah_pendidikanfreepik__adorable-cartoon-style-indonesian-education-after-__62014_fye57v.jpg","tags":["Sejarah","Pendidikan"]}','true','/artikel/sejarah-pendidilan','{"title":"Sejarah Pendidikan di Indonesia: Perkembangan dan Transformasi dari Masa ke Masa","description":"Sejarah pendidikan di Indonesia mencakup perkembangan dari sistem tradisional hingga era modern. Artikel ini mengulas perjalanan pendidikan Indonesia dari masa kerajaan, penjajahan Belanda, pendudukan Jepang, hingga pasca kemerdekaan, serta tantangan dan harapan di masa depan."}','artikel/1.sejarah pendidilan','qEGDNkXA2d09eKBlSOju1ucxa8LT-QAYHYDoFhBThSM');
INSERT INTO "_content_search" VALUES('search/artikel/2.raport-pendidikan.md','Rapor Pendidikan: Pengertian, Fungsi, dan Manfaat dalam Peningkatan Mutu Sekolah','{"type":"minimark","value":[["p",{},"Rapor pendidikan adalah salah satu instrumen evaluasi bagi sekolah dan pemerintah dalam memantau perkembangan dan mutu pendidikan di berbagai jenjang. Artikel ini akan membahas mengenai definisi, fungsi, manfaat, serta bagaimana rapor pendidikan digunakan. Selain itu, akan dijelaskan peran Asesmen Nasional Berbasis Komputer (ANBK) dalam menyediakan data untuk rapor pendidikan, serta berbagai informasi yang dapat diperoleh dari laporan ini untuk pengambilan keputusan."],["h2",{"id":"apa-itu-rapor-pendidikan"},"Apa Itu Rapor Pendidikan?"],["p",{},"Rapor pendidikan adalah sistem laporan berbasis data yang memuat informasi tentang capaian pendidikan sekolah, seperti kualitas hasil belajar, lingkungan belajar, dan efektivitas manajemen sekolah. Rapor ini digunakan oleh pemerintah dan sekolah untuk melihat aspek-aspek yang masih perlu ditingkatkan."],["h2",{"id":"fungsi-dan-manfaat-rapor-pendidikan"},"Fungsi dan Manfaat Rapor Pendidikan"],["p",{},"Rapor pendidikan berfungsi sebagai alat evaluasi yang objektif dan akurat untuk mengetahui capaian mutu pendidikan. Berikut manfaatnya:"],["ul",{},["li",{},["strong",{},"Meningkatkan Kualitas Pembelajaran:"]," Sekolah dapat mengetahui area yang memerlukan perbaikan."],["li",{},["strong",{},"Dasar Pengambilan Keputusan:"]," Pemerintah dan sekolah dapat membuat kebijakan berbasis data."],["li",{},["strong",{},"Memantau Perkembangan Sekolah:"]," Setiap tahun, rapor pendidikan memberikan gambaran apakah sekolah mengalami peningkatan mutu atau tidak."],["li",{},["strong",{},"Transparansi Publik:"]," Informasi mutu sekolah dapat diakses sebagai bentuk akuntabilitas pendidikan."]],["h2",{"id":"apa-itu-rapor-mutu-pendidikan"},"Apa Itu Rapor Mutu Pendidikan?"],["p",{},"Rapor mutu pendidikan adalah bagian dari rapor pendidikan yang lebih fokus pada aspek kualitas dan efektivitas sekolah, termasuk komponen proses pembelajaran, kualitas guru, dan manajemen sekolah. Ini merupakan bagian penting untuk melihat apakah standar nasional pendidikan sudah terpenuhi atau belum."],["h2",{"id":"masuk-rapor-pendidikan-menggunakan-akun-apa"},"Masuk Rapor Pendidikan Menggunakan Akun Apa?"],["p",{},"Untuk mengakses rapor pendidikan, pengguna (kepala sekolah atau admin) harus menggunakan akun ",["strong",{},"Dapodik"]," atau ",["strong",{},"akun dinas pendidikan"]," terkait. Akun ini telah terintegrasi dengan data sekolah yang ada di pusat, sehingga akses hanya diberikan kepada pihak-pihak yang berwenang."],["h2",{"id":"kapan-rapor-pendidikan-dapat-digunakan"},"Kapan Rapor Pendidikan Dapat Digunakan?"],["p",{},"Rapor pendidikan dapat diakses dan dimanfaatkan setelah ",["strong",{},"Asesmen Nasional Berbasis Komputer (ANBK)"]," dan evaluasi tahunan selesai. Biasanya, rapor ini tersedia pada awal tahun berikutnya setelah data ANBK dan hasil pemetaan disusun."],["h2",{"id":"untuk-apa-hasil-anbk"},"Untuk Apa Hasil ANBK?"],["p",{},["img",{"alt":"ANBK","src":"https://res.cloudinary.com/dyy24w5kl/image/upload/v1730100640/artikel/ujian1_dkq4xb.png","height":900,"width":1600}]],["p",{},"Hasil ANBK digunakan untuk memetakan capaian kompetensi siswa dan kondisi sekolah secara keseluruhan. Informasi ini menjadi dasar bagi:"],["ul",{},["li",{},"Perbaikan kurikulum dan proses belajar mengajar."],["li",{},"Penyusunan program peningkatan mutu sekolah."],["li",{},"Evaluasi kebijakan pendidikan nasional dan daerah."],["li",{},"Memonitor ketimpangan pendidikan di berbagai wilayah."]],["h2",{"id":"informasi-apa-yang-dapat-diambil-dari-rapor-pendidikan"},"Informasi Apa yang Dapat Diambil dari Rapor Pendidikan?"],["p",{},["img",{"alt":"Raport Pendidikan","src":"https://res.cloudinary.com/dyy24w5kl/image/upload/v1730100644/artikel/MQZCZrqlzK_mjx360.png"}]],["p",{},"Rapor pendidikan berisi beberapa poin penting seperti:"],["ul",{},["li",{},["strong",{},"Capaian Kompetensi Dasar:"]," Seperti kemampuan literasi dan numerasi siswa."],["li",{},["strong",{},"Kondisi Lingkungan Sekolah:"]," Tingkat keamanan dan kenyamanan."],["li",{},["strong",{},"Kualitas Guru:"]," Tingkat profesionalisme dan kinerja guru."],["li",{},["strong",{},"Partisipasi Siswa dan Orang Tua:"]," Tingkat keterlibatan dalam pembelajaran."],["li",{},["strong",{},"Manajemen dan Kepemimpinan Sekolah:"]," Efektivitas pengelolaan sekolah."]],["h2",{"id":"kesimpulan"},"Kesimpulan"],["p",{},"Rapor pendidikan dan rapor mutu pendidikan merupakan alat penting untuk memastikan bahwa setiap sekolah mencapai standar yang diharapkan. Dengan adanya rapor ini, sekolah, pemerintah, dan pemangku kepentingan lainnya dapat bekerja sama untuk meningkatkan mutu pendidikan di Indonesia. Hasil ANBK berperan penting dalam mendukung evaluasi dan perencanaan pendidikan yang lebih baik."]],"toc":{"title":"","searchDepth":2,"depth":2,"links":[{"id":"apa-itu-rapor-pendidikan","depth":2,"text":"Apa Itu Rapor Pendidikan?"},{"id":"fungsi-dan-manfaat-rapor-pendidikan","depth":2,"text":"Fungsi dan Manfaat Rapor Pendidikan"},{"id":"apa-itu-rapor-mutu-pendidikan","depth":2,"text":"Apa Itu Rapor Mutu Pendidikan?"},{"id":"masuk-rapor-pendidikan-menggunakan-akun-apa","depth":2,"text":"Masuk Rapor Pendidikan Menggunakan Akun Apa?"},{"id":"kapan-rapor-pendidikan-dapat-digunakan","depth":2,"text":"Kapan Rapor Pendidikan Dapat Digunakan?"},{"id":"untuk-apa-hasil-anbk","depth":2,"text":"Untuk Apa Hasil ANBK?"},{"id":"informasi-apa-yang-dapat-diambil-dari-rapor-pendidikan","depth":2,"text":"Informasi Apa yang Dapat Diambil dari Rapor Pendidikan?"},{"id":"kesimpulan","depth":2,"text":"Kesimpulan"}]}}','Rapor pendidikan adalah salah satu instrumen evaluasi bagi sekolah dan pemerintah dalam memantau perkembangan dan mutu pendidikan di berbagai jenjang.','md','{"date":"2024-10-28T00:00:00.000Z","author":"Dinar Permadi","image":"https://res.cloudinary.com/dyy24w5kl/image/upload/v1730100651/artikel/BUeNWYemFS_v3ynrq.png","tags":["Guru","Raport Mutu"]}','true','/artikel/raport-pendidikan','{"title":"Rapor Pendidikan: Pengertian, Fungsi, dan Manfaat dalam Peningkatan Mutu Sekolah","description":"Rapor pendidikan adalah salah satu instrumen evaluasi bagi sekolah dan pemerintah dalam memantau perkembangan dan mutu pendidikan di berbagai jenjang."}','artikel/2.raport-pendidikan','1bpLO4xUbeABfA_96VKkp1jXbh0D0lgAFsCywAyKwww');
INSERT INTO "_content_search" VALUES('search/artikel/3.penerimaan-peserta-didik-baru.md','PPDB SD 2025: Sistem, Syarat, Jadwal, dan Prosedur Terbaru','{"type":"minimark","value":[["p",{},"Penerimaan Peserta Didik Baru (PPDB) untuk jenjang Sekolah Dasar (SD) tahun 2025 mengalami perubahan signifikan. Pemerintah resmi mengganti istilah PPDB menjadi Sistem Penerimaan Murid Baru (SPMB) mulai tahun ajaran 2025/2026. Berikut ulasan lengkap mengenai SPMB SD 2025, mulai dari syarat, jalur pendaftaran, jadwal, hingga dokumen yang perlu disiapkan."],["h2",{"id":"perubahan-sistem-ppdb-menjadi-spmb"},["strong",{},"Perubahan Sistem: PPDB Menjadi SPMB"]],["p",{},"Mulai tahun 2025, proses penerimaan siswa baru di seluruh Indonesia tidak lagi menggunakan istilah PPDB, melainkan SPMB (Sistem Penerimaan Murid Baru). Pergantian ini diatur dalam Permendikdasmen No 3 Tahun 2025 dan bertujuan untuk meningkatkan transparansi, keadilan, serta kemudahan akses pendaftaran melalui sistem online di semua jenjang pendidikan, termasuk SD."],["h2",{"id":"jalur-pendaftaran-spmb-sd-2025"},["strong",{},"Jalur Pendaftaran SPMB SD 2025"]],["p",{},"Terdapat tiga jalur utama dalam SPMB SD 2025 yang menggantikan sistem zonasi pada PPDB sebelumnya124:"],["ul",{},["li",{},["strong",{},"Jalur Domisili (Zonasi):"]," Untuk anak yang berdomisili di sekitar wilayah sekolah. Dibuktikan dengan Kartu Keluarga (KK) yang sudah diterbitkan minimal 1 tahun sebelum pendaftaran."],["li",{},["strong",{},"Jalur Afirmasi:"]," Diperuntukkan bagi anak dari keluarga kurang mampu, penyandang disabilitas, atau kelompok rentan lainnya. Bukti berupa KIP, KKS, atau surat keterangan disabilitas."],["li",{},["strong",{},"Jalur Mutasi:"]," Untuk anak yang mengikuti perpindahan orang tua/guru karena tugas. Bukti berupa surat tugas, surat pindah domisili, dan KK terbaru."]],["h2",{"id":"syarat-umum-dan-khusus-masuk-sd-2025"},["strong",{},"Syarat Umum dan Khusus Masuk SD 2025"]],["p",{},["strong",{},"Syarat usia dan dokumen penting yang wajib dipenuhi calon peserta didik SD tahun 2025 adalah sebagai berikut:"]],["ul",{},["li",{},["strong",{},"Usia Minimal:"],["ul",{},["li",{},"Usia 7 tahun per 1 Juli 2025 diprioritaskan diterima."],["li",{},"Usia minimal 6 tahun per 1 Juli 2025 diperbolehkan mendaftar."],["li",{},"Usia minimal 5 tahun 6 bulan per 1 Juli 2025 dapat mendaftar jika memiliki kecerdasan dan/atau bakat istimewa serta kesiapan psikis, dibuktikan dengan rekomendasi tertulis dari psikolog profesional atau dewan guru jika psikolog tidak tersedia."]]],["li",{},["strong",{},"Dokumen Wajib:"],["ul",{},["li",{},"Akta kelahiran atau surat keterangan lahir yang dilegalisasi pejabat berwenang."],["li",{},"Kartu Keluarga (KK) yang diterbitkan minimal 1 tahun sebelum pendaftaran."],["li",{},"Pas foto terbaru calon siswa."],["li",{},"Ijazah TK atau Surat Keterangan Lulus (jika ada)."]]],["li",{},["strong",{},"Khusus Penyandang Disabilitas atau Daerah 3T:"]," Syarat usia dapat dikecualikan untuk anak penyandang disabilitas, SD layanan khusus (SDLB), dan SD di daerah tertinggal, terdepan, dan terluar (3T)."],["li",{},["strong",{},"Tidak Ada Tes Calistung:"]," Seleksi masuk SD tidak boleh menggunakan tes membaca, menulis, dan berhitung (calistung)."]],["h2",{"id":"jadwal-pendaftaran-spmb-sd-2025"},["strong",{},"Jadwal Pendaftaran SPMB SD 2025"]],["p",{},"Jadwal pendaftaran SPMB SD tahun 2025 umumnya berlangsung mulai awal Mei hingga Juli 2025. Namun, jadwal pasti bisa berbeda di tiap daerah sesuai kebijakan pemerintah daerah masing-masing."],["p",{},"Berikut gambaran umum tahapan SPMB SD 2025:"],["ul",{},["li",{},["strong",{},"Penetapan Wilayah & Kuota:"]," Maret 2025"],["li",{},["strong",{},"Pengumuman Pendaftaran:"]," Minggu pertama Mei 2025"],["li",{},["strong",{},"Pendaftaran Jalur Afirmasi & Mutasi:"]," Awal hingga pertengahan Juni 2025"],["li",{},["strong",{},"Pendaftaran Jalur Domisili:"]," Pertengahan hingga akhir Juni 2025"],["li",{},["strong",{},"Seleksi & Pengumuman Hasil:"]," Sesuai kebijakan sekolah masing-masing"],["li",{},["strong",{},"Integrasi Data Murid Baru:"]," Agustus 2025."]],["h2",{"id":"prosedur-pendaftaran-online"},["strong",{},"Prosedur Pendaftaran Online"]],["p",{},"SPMB SD 2025 dilakukan secara daring melalui portal resmi SPMB di setiap provinsi atau kabupaten/kota. Calon peserta didik atau orang tua wajib membuat akun, mengunggah dokumen persyaratan, memilih jalur pendaftaran, dan memilih sekolah tujuan sesuai domisili atau jalur yang diambil."],["p",{},["img",{"alt":"ppdb","src":"/artikel/ppdb.png"}]],["h2",{"id":"tips-dan-catatan-penting"},["strong",{},"Tips dan Catatan Penting"]],["ul",{},["li",{},"Selalu pantau pengumuman resmi dari Dinas Pendidikan setempat dan website SPMB daerah Anda."],["li",{},"Pastikan semua dokumen asli dan fotokopi telah disiapkan serta dilegalisasi sesuai ketentuan."],["li",{},"Jika terjadi perubahan data pada KK kurang dari 1 tahun, pastikan perubahan tersebut sesuai dengan ketentuan yang berlaku, seperti penambahan anggota keluarga atau pengurangan akibat meninggal dunia/pindah."]],["h2",{"id":"kesimpulan"},["strong",{},"Kesimpulan"]],["p",{},"Sistem penerimaan siswa baru SD tahun 2025 kini lebih transparan, mudah, dan inklusif melalui SPMB. Orang tua dan calon peserta didik wajib memahami syarat, jalur, serta jadwal pendaftaran agar proses berjalan lancar. Pastikan selalu mengikuti informasi resmi dari instansi pendidikan terkait untuk menghindari kesalahan saat mendaftar."]],"toc":{"title":"","searchDepth":2,"depth":2,"links":[{"id":"perubahan-sistem-ppdb-menjadi-spmb","depth":2,"text":"Perubahan Sistem: PPDB Menjadi SPMB"},{"id":"jalur-pendaftaran-spmb-sd-2025","depth":2,"text":"Jalur Pendaftaran SPMB SD 2025"},{"id":"syarat-umum-dan-khusus-masuk-sd-2025","depth":2,"text":"Syarat Umum dan Khusus Masuk SD 2025"},{"id":"jadwal-pendaftaran-spmb-sd-2025","depth":2,"text":"Jadwal Pendaftaran SPMB SD 2025"},{"id":"prosedur-pendaftaran-online","depth":2,"text":"Prosedur Pendaftaran Online"},{"id":"tips-dan-catatan-penting","depth":2,"text":"Tips dan Catatan Penting"},{"id":"kesimpulan","depth":2,"text":"Kesimpulan"}]}}','Penerimaan Peserta Didik Baru (PPDB) untuk jenjang Sekolah Dasar (SD) tahun 2025 mengalami perubahan signifikan. Pemerintah resmi mengganti istilah PPDB menjadi Sistem Penerimaan Murid Baru (SPMB) mulai tahun ajaran 2025/2026. Berikut ulasan lengkap mengenai SPMB SD 2025, mulai dari syarat, jalur pendaftaran, jadwal, hingga dokumen yang perlu disiapkan.','md','{"date":"2025-06-22T00:00:00.000Z","author":"Dinar Permadi","image":"https://res.cloudinary.com/dyy24w5kl/image/upload/v1752354397/artikel/artikel-ppdb_xwnmne.png","tags":["Guru","PPDB","Siswa"]}','true','/artikel/penerimaan-peserta-didik-baru','{"title":"PPDB SD 2025: Sistem, Syarat, Jadwal, dan Prosedur Terbaru","description":"Penerimaan Peserta Didik Baru (PPDB) untuk jenjang Sekolah Dasar (SD) tahun 2025 mengalami perubahan signifikan. Pemerintah resmi mengganti istilah PPDB menjadi Sistem Penerimaan Murid Baru (SPMB) mulai tahun ajaran 2025/2026. Berikut ulasan lengkap mengenai SPMB SD 2025, mulai dari syarat, jalur pendaftaran, jadwal, hingga dokumen yang perlu disiapkan."}','artikel/3.penerimaan-peserta-didik-baru','pEjj5sTPvZ8JiYAOvXCszmWktshHhUIR7JmMYD-UpuM');
INSERT INTO "_content_search" VALUES('search/berita/1.anbk-2024.md','ANBK (Asesmen Nasional Berbasis Komputer) 2024','{"type":"minimark","value":[["h1",{"id":"anbk-2024"},"ANBK 2024"],["p",{},"ANBK (Asesmen Nasional Berbasis Komputer) untuk jenjang SD tahun 2024 akan dimulai pada 28 Oktober hingga 4 November 2024. Untuk SD sendiri khusu siswa kelas 5 yang akan berpartisipasi. Tujuan utama ANBK (Asesmen Nasional Berbasis Komputer) adalah untuk mengevaluasi mutu pendidikan melalui pengukuran kompetensi dasar siswa dalam literasi dan numerasi, serta survei lingkungan belajar. Hasil dari ANBK digunakan sebagai acuan bagi sekolah dan pemerintah untuk meningkatkan kualitas pendidikan, memastikan pembelajaran lebih relevan dengan kebutuhan siswa, dan menciptakan lingkungan pendidikan yang lebih baik bagi seluruh peserta didik"],["p",{},"Pelaksanaan ANBK dibagi dalam beberapa tahap dengan beberapa sekolah menyiapkan teknisi, proktor, dan pengawas untuk mendukung kelancaran proses. ",["strong",{},"SDN Teja 2"]," pada gelombang 1 sesi ke-2 yang akan di laksanakan besok jam 10."]],"toc":{"title":"","searchDepth":2,"depth":2,"links":[]}}','ANBK (Asesmen Nasional Berbasis Komputer) untuk jenjang SD tahun 2024 akan dimulai pada 28 Oktober hingga 4 November 2024.','md','{"date":"2024-10-27T00:00:00.000Z","tags":["ANBK","Asesmen"]}','true','/berita/anbk-2024','{"title":"ANBK (Asesmen Nasional Berbasis Komputer) 2024","description":"ANBK (Asesmen Nasional Berbasis Komputer) untuk jenjang SD tahun 2024 akan dimulai pada 28 Oktober hingga 4 November 2024."}','berita/1.anbk-2024','XDnFEAqv6ny7OmypvY3n4-wUSlA3nts4-DHzcAs3Ci8');
INSERT INTO "_content_search" VALUES('search/berita/2.pergantian-kepala-sekolah-bu-ely-ditunjuk-sebagai-plt-menggantikan-pak-yusup.md','Pergantian Kepala Sekolah: Bu Ely Ditunjuk Sebagai PLT Menggantikan Pak Yusup','{"type":"minimark","value":[["p",{},["strong",{},"SDN Teja II"]," – Setelah dua tahun masa kepemimpinan Pak Yusup sebagai Kepala Sekolah, SDN Teja II kini resmi dipimpin oleh Bu Ely, yang ditunjuk sebagai Pelaksana Tugas (PLT). Bu Ely juga menjabat sebagai Kepala Sekolah di SDN Pajajar 1, sehingga posisinya di SDN Teja II bersifat sementara hingga penunjukan Kepala Sekolah definitif."],["h2",{"id":"terima-kasih-atas-pengabdian-pak-yusup"},"Terima Kasih atas Pengabdian Pak Yusup"],["p",{},"Pak Yusup telah memimpin SDN Teja II selama dua tahun, membawa berbagai kemajuan dan pencapaian penting bagi sekolah. Dalam pidato perpisahannya, Pak Yusup menyampaikan rasa syukur dan kebanggaan atas kerja sama yang erat dengan seluruh elemen sekolah."],["p",{},"\"Dua tahun di SDN Teja II adalah perjalanan yang penuh tantangan sekaligus kebanggaan. Saya berterima kasih kepada seluruh guru, siswa, dan orang tua atas dukungan yang luar biasa. Semoga sekolah ini terus maju di bawah kepemimpinan Bu Ely,\" ujar beliau."],["h2",{"id":"bu-ely-komitmen-untuk-menjaga-kelangsungan-program-sekolah"},"Bu Ely: Komitmen untuk Menjaga Kelangsungan Program Sekolah"],["p",{},"Sebagai PLT, Bu Ely hadir dengan komitmen untuk menjaga kesinambungan program yang sudah berjalan di SDN Teja II. Dalam sambutannya, beliau menegaskan bahwa peran PLT ini akan dijalankan dengan penuh tanggung jawab, meskipun posisinya bersifat sementara."],["p",{},"\"Saya diamanahi tugas ini untuk sementara waktu, namun saya akan memastikan semua program dan aktivitas di sekolah tetap berjalan dengan baik. Dukungan dari seluruh pihak sangat saya harapkan,\" ungkap Bu Ely."],["h2",{"id":"proses-penunjukan-plt-kepala-sekolah"},"Proses Penunjukan PLT Kepala Sekolah"],["p",{},"Penunjukan Bu Ely sebagai PLT Kepala Sekolah di SDN Teja II dilakukan berdasarkan arahan dari Dinas Pendidikan, sesuai dengan ketentuan dalam ",["strong",{},"Permendikbud Nomor 6 Tahun 2018 tentang Penugasan Guru sebagai Kepala Sekolah"],". Regulasi ini memungkinkan penunjukan Pelaksana Tugas pada situasi tertentu, termasuk masa transisi seperti saat ini."],["p",{},"Dengan pengalaman beliau memimpin SDN Pajajar 1, diharapkan Bu Ely dapat menjalankan tugas di SDN Teja II dengan optimal, hingga terpilihnya Kepala Sekolah definitif."],["h2",{"id":"harapan-untuk-masa-depan-sekolah"},"Harapan untuk Masa Depan Sekolah"],["p",{},"Pergantian kepemimpinan ini menjadi momen penting untuk melanjutkan visi dan misi SDN Teja II sebagai lembaga pendidikan yang unggul. Seluruh warga sekolah, termasuk guru, staf, siswa, dan orang tua, diharapkan dapat memberikan dukungan penuh kepada Bu Ely dalam masa transisi ini."],["p",{},"Terima kasih, Pak Yusup, atas dedikasi dan kontribusinya selama dua tahun terakhir. Selamat bertugas, Bu Ely, sebagai PLT Kepala Sekolah di SDN Teja II. Semoga SDN Teja II terus maju dan berprestasi."]],"toc":{"title":"","searchDepth":2,"depth":2,"links":[{"id":"terima-kasih-atas-pengabdian-pak-yusup","depth":2,"text":"Terima Kasih atas Pengabdian Pak Yusup"},{"id":"bu-ely-komitmen-untuk-menjaga-kelangsungan-program-sekolah","depth":2,"text":"Bu Ely: Komitmen untuk Menjaga Kelangsungan Program Sekolah"},{"id":"proses-penunjukan-plt-kepala-sekolah","depth":2,"text":"Proses Penunjukan PLT Kepala Sekolah"},{"id":"harapan-untuk-masa-depan-sekolah","depth":2,"text":"Harapan untuk Masa Depan Sekolah"}]}}','SDN Teja II – Setelah dua tahun masa kepemimpinan Pak Yusup sebagai Kepala Sekolah, SDN Teja II kini resmi dipimpin oleh Bu Ely, yang ditunjuk sebagai Pelaksana Tugas (PLT). Bu Ely juga menjabat sebagai Kepala Sekolah di SDN Pajajar 1, sehingga posisinya di SDN Teja II bersifat sementara hingga penunjukan Kepala Sekolah definitif..','md','{"date":"2024-11-11T00:00:00.000Z","tags":["Guru","Kepala Sekolah"]}','true','/berita/pergantian-kepala-sekolah-bu-ely-ditunjuk-sebagai-plt-menggantikan-pak-yusup','{"title":"Pergantian Kepala Sekolah: Bu Ely Ditunjuk Sebagai PLT Menggantikan Pak Yusup","description":"SDN Teja II – Setelah dua tahun masa kepemimpinan Pak Yusup sebagai Kepala Sekolah, SDN Teja II kini resmi dipimpin oleh Bu Ely, yang ditunjuk sebagai Pelaksana Tugas (PLT). Bu Ely juga menjabat sebagai Kepala Sekolah di SDN Pajajar 1, sehingga posisinya di SDN Teja II bersifat sementara hingga penunjukan Kepala Sekolah definitif.."}','berita/2.pergantian-kepala-sekolah-bu-ely-ditunjuk-sebagai-plt-menggantikan-pak-yusup','IBevap8cqMz6tqgYoaYY9cFoEFmVPYm_qaMnwNgtHh8');
INSERT INTO "_content_search" VALUES('search/berita/3.pembelajaran-bulan-ramadan.md','Revisi Pembelajaran Selama Bulan Ramadan 2025','{"type":"minimark","value":[["p",{},["img",{"alt":"Revisi Pembelajaran Selama Bulan Ramadan 2025","src":"/artikel/revisi.jpeg"}]],["p",{},"Pemerintah Indonesia melalui Kementerian Pendidikan Dasar dan Menengah (Kemendikdasmen), Kementerian Agama (Kemenag), dan Kementerian Dalam Negeri (Kemendagri) telah mengeluarkan Surat Edaran Bersama (SEB) terkait revisi jadwal pembelajaran selama Bulan Ramadan 1446 Hijriah atau tahun 2025 Masehi. Kebijakan ini bertujuan untuk menyesuaikan kegiatan belajar dengan suasana ibadah Ramadan serta mendukung kelancaran arus mudik Lebaran."],["p",{},"Berdasarkan ",["strong",{},"SEB"]," terbaru, pembelajaran akan dilakukan dalam beberapa tahap:"],["ol",{},["li",{},["strong",{},"27 Februari - 5 Maret 2025"],": Kegiatan pembelajaran dilakukan secara mandiri di rumah, tempat ibadah, atau lingkungan masyarakat."],["li",{},["strong",{},"6 - 20 Maret 2025"],": Pembelajaran kembali dilaksanakan di sekolah atau madrasah dengan penyesuaian jam belajar."],["li",{},["strong",{},"21 Maret - 8 April 2025"],": Libur bersama Idulfitri untuk memberikan waktu bagi siswa dan keluarga mempersiapkan perayaan Lebaran."],["li",{},["strong",{},"9 April 2025"],": Kegiatan belajar mengajar kembali normal."]],["p",{},"Selama Ramadan, siswa diharapkan mengikuti kegiatan yang memperkuat nilai-nilai keagamaan, seperti tadarus Al-Qur''an, pesantren kilat, dan kegiatan sosial. Bagi siswa non-Muslim, kegiatan keagamaan sesuai keyakinan masing-masing juga dianjurkan."],["p",{},"Menteri Pendidikan Dasar dan Menengah, Abdul Mu’ti, menyatakan bahwa kebijakan ini diharapkan dapat meningkatkan iman, takwa, dan karakter mulia siswa. Selain itu, Menteri Perhubungan, Dudy Purwagandhi, mengapresiasi langkah ini karena dapat membantu mengurangi kepadatan lalu lintas selama arus mudik."],["p",{},"Dengan adanya revisi ini, pemerintah berharap seluruh siswa dapat menjalani Ramadan dengan penuh makna, sekaligus mendukung kelancaran mudik Lebaran 2025."]],"toc":{"title":"","searchDepth":2,"depth":2,"links":[]}}','Pemerintah Indonesia menetapkan kebijakan baru untuk jadwal pembelajaran selama Bulan Ramadan 1446 Hijriah. Revisi ini bertujuan untuk menyesuaikan kegiatan belajar dengan suasana ibadah Ramadan, memperkuat nilai-nilai keagamaan siswa, dan mendukung kelancaran arus mudik Lebaran.','md','{"date":"2025-03-07T00:00:00.000Z","tags":["Pembelajaran","Ramadan"]}','true','/berita/pembelajaran-bulan-ramadan','{"title":"Revisi Pembelajaran Selama Bulan Ramadan 2025","description":"Pemerintah Indonesia menetapkan kebijakan baru untuk jadwal pembelajaran selama Bulan Ramadan 1446 Hijriah. Revisi ini bertujuan untuk menyesuaikan kegiatan belajar dengan suasana ibadah Ramadan, memperkuat nilai-nilai keagamaan siswa, dan mendukung kelancaran arus mudik Lebaran."}','berita/3.pembelajaran-bulan-ramadan','eLw1JBmp-M1bjNbZjDvh6MM61FzwMFwe0gZeVkWkL_c');
INSERT INTO "_content_search" VALUES('search/berita/4.Serah Terima Jabatan Kepala Sekolah copy.md','Serah Terima Jabatan Kepala Sekolah SDN Teja II Maret Tahun 2025','{"type":"minimark","value":[["p",{},"Momen bersejarah dan penuh haru mewarnai SDN Teja II pada Maret 2025. Setelah mengemban amanah sebagai Pelaksana Tugas (PLT) Kepala Sekolah selama empat bulan, Ibu Ely Sri, S.Pd., dengan tulus menyerahkan tongkat estafet kepemimpinan kepada Ibu Susi Susanti, S.Pd., sebagai Kepala Sekolah definitif."],["p",{},"Acara serah terima jabatan ini dihadiri oleh seluruh dewan guru, staf tata usaha, perwakilan komite sekolah, serta beberapa siswa yang turut menjadi saksi pergantian kepemimpinan ini. Suasana khidmat terasa sejak awal acara, dimulai dengan menyanyikan lagu Indonesia Raya dan dilanjutkan dengan pembacaan doa."],["p",{},"Dalam sambutannya, Ibu Ely Sri menyampaikan rasa terima kasih yang mendalam atas dukungan dan kerja sama yang telah diberikan oleh seluruh warga sekolah selama masa jabatannya. \"Empat bulan ini adalah waktu yang singkat, namun penuh makna. Saya bangga bisa menjadi bagian dari perjalanan SDN Teja II dan menyaksikan semangat belajar yang luar biasa dari para siswa,\" ujar Ibu Ely. Beliau juga berpesan agar seluruh warga sekolah terus mendukung Ibu Susi Susanti dalam menjalankan tugasnya sebagai kepala sekolah yang baru."],["p",{},"Sementara itu, Ibu Susi Susanti, dalam pidato pertamanya sebagai Kepala Sekolah SDN Teja II, menyampaikan rasa syukur dan terima kasih atas kepercayaan yang diberikan kepadanya. \"Saya merasa terhormat dan siap mengemban amanah ini. Bersama-sama, mari kita lanjutkan perjuangan untuk meningkatkan kualitas pendidikan di sekolah kita tercinta ini,\" kata Ibu Susi. Beliau juga mengajak seluruh elemen sekolah untuk bersinergi dan berkolaborasi dalam mewujudkan visi dan misi sekolah."],["p",{},"Acara serah terima jabatan ini diakhiri dengan penandatanganan berita acara serah terima jabatan, penyerahan memori jabatan dari Ibu Ely Sri kepada Ibu Susi Susanti, serta pemberian cenderamata sebagai ungkapan terima kasih dari seluruh warga sekolah kepada Ibu Ely."],["p",{},"Dengan semangat baru dan kepemimpinan yang baru, SDN Teja II siap melangkah maju menuju masa depan pendidikan yang lebih gemilang. Selamat bertugas, Ibu Susi Susanti!"]],"toc":{"title":"","searchDepth":2,"depth":2,"links":[]}}','Pemerintah Indonesia menetapkan kebijakan baru untuk jadwal pembelajaran selama Bulan Ramadan 1446 Hijriah. Revisi ini bertujuan untuk menyesuaikan kegiatan belajar dengan suasana ibadah Ramadan, memperkuat nilai-nilai keagamaan siswa, dan mendukung kelancaran arus mudik Lebaran.','md','{"date":"2025-03-12T00:00:00.000Z","tags":["Guru"]}','true','/berita/serah-terima-jabatan-kepala-sekolah-copy','{"title":"Serah Terima Jabatan Kepala Sekolah SDN Teja II Maret Tahun 2025","description":"Pemerintah Indonesia menetapkan kebijakan baru untuk jadwal pembelajaran selama Bulan Ramadan 1446 Hijriah. Revisi ini bertujuan untuk menyesuaikan kegiatan belajar dengan suasana ibadah Ramadan, memperkuat nilai-nilai keagamaan siswa, dan mendukung kelancaran arus mudik Lebaran."}','berita/4.Serah Terima Jabatan Kepala Sekolah copy','OmweIFJvUjGqj8YWRBl-QAM8BNsmTcODqTAGFUh73Gw');
INSERT INTO "_content_search" VALUES('search/berita/5.Hari Efektif.md','SDN Teja II Terapkan 5 Hari Sekolah Mulai Tahun Ajaran Baru, Jadwal Efektif dan Karakter Siswa Lebih Optimal','{"type":"minimark","value":[["h2",{"id":"kebijakan-baru-jadwal-sekolah-selama-ramadan"},"Kebijakan Baru Jadwal Sekolah Selama Ramadan"],["p",{},"Pemerintah Indonesia melalui Dinas Pendidikan Kabupaten Majalengka telah mengeluarkan kebijakan penyesuaian jam efektif belajar selama Ramadan. Tujuannya adalah:"],["ul",{},["li",{},"Menyesuaikan kegiatan belajar dengan suasana ibadah Ramadan."],["li",{},"Memperkuat nilai-nilai keagamaan siswa."],["li",{},"Mendukung kelancaran arus mudik Lebaran."]],["h2",{"id":"jadwal-pembelajaran-sdn-teja-ii-tahun-ajaran-baru"},"Jadwal Pembelajaran SDN Teja II Tahun Ajaran Baru"],["p",{},"Mulai tahun ajaran 2025/2026, SDN Teja II menerapkan sistem lima hari sekolah dalam seminggu, dengan rincian sebagai berikut:"],["table",{},["thead",{},["tr",{},["th",{},"Hari"],["th",{},"Jam Masuk"],["th",{},"Jam Pulang"],["th",{},"Keterangan"]]],["tbody",{},["tr",{},["td",{},"Senin-Kamis"],["td",{},"06.30 WIB"],["td",{},"Selesai KBM"],["td",{},"Termasuk istirahat 30 menit"]],["tr",{},["td",{},"Jumat"],["td",{},"06.30 WIB"],["td",{},"Selesai KBM"],["td",{},"Termasuk istirahat 45 menit (ibadah)"]]]],["ul",{},["li",{},["strong",{},"Kelas I & II:"]," Minimal 7 jam pelajaran per hari (1 JP = 35 menit)."],["li",{},["strong",{},"Kelas III–VI:"]," Minimal 8,5 JP per hari Senin–Kamis, dan 6 JP pada Jumat."]],["h2",{"id":"manfaat-kebijakan"},"Manfaat Kebijakan"],["ul",{},["li",{},"Memberikan waktu lebih bagi siswa untuk beribadah, berkegiatan keluarga, dan sosial."],["li",{},"Mendukung pembentukan karakter Pancawaluya: Bageur, Cageur, Bener, Pinter, Singer."],["li",{},"Memudahkan penyesuaian selama Ramadan dan arus mudik Lebaran."]],["h2",{"id":"komitmen-sdn-teja-ii"},"Komitmen SDN Teja II"],["p",{},"SDN Teja II siap menjalankan kebijakan ini dengan optimal, memastikan seluruh guru dan tenaga kependidikan berkolaborasi untuk menciptakan lingkungan belajar yang kondusif, efektif, dan ramah anak. Seluruh kegiatan ekstrakurikuler dan pembiasaan positif tetap berjalan sesuai program sekolah."]],"toc":{"title":"","searchDepth":2,"depth":2,"links":[{"id":"kebijakan-baru-jadwal-sekolah-selama-ramadan","depth":2,"text":"Kebijakan Baru Jadwal Sekolah Selama Ramadan"},{"id":"jadwal-pembelajaran-sdn-teja-ii-tahun-ajaran-baru","depth":2,"text":"Jadwal Pembelajaran SDN Teja II Tahun Ajaran Baru"},{"id":"manfaat-kebijakan","depth":2,"text":"Manfaat Kebijakan"},{"id":"komitmen-sdn-teja-ii","depth":2,"text":"Komitmen SDN Teja II"}]}}','SDN Teja II resmi menerapkan kebijakan sekolah lima hari kerja mulai tahun ajaran 2025/2026 sesuai Surat Edaran Dinas Pendidikan Kabupaten Majalengka. Jadwal baru ini mengoptimalkan jam belajar efektif, mendukung pembentukan karakter Pancawaluya, dan menyesuaikan kebutuhan siswa selama Ramadan serta arus mudik Lebaran. Temukan rincian jadwal, manfaat, dan komitmen sekolah dalam meningkatkan mutu pendidikan di SDN Teja II.','md','{"date":"2025-07-12T00:00:00.000Z","tags":["Pengumuman"]}','true','/berita/hari-efektif','{"title":"SDN Teja II Terapkan 5 Hari Sekolah Mulai Tahun Ajaran Baru, Jadwal Efektif dan Karakter Siswa Lebih Optimal","description":"SDN Teja II resmi menerapkan kebijakan sekolah lima hari kerja mulai tahun ajaran 2025/2026 sesuai Surat Edaran Dinas Pendidikan Kabupaten Majalengka. Jadwal baru ini mengoptimalkan jam belajar efektif, mendukung pembentukan karakter Pancawaluya, dan menyesuaikan kebutuhan siswa selama Ramadan serta arus mudik Lebaran. Temukan rincian jadwal, manfaat, dan komitmen sekolah dalam meningkatkan mutu pendidikan di SDN Teja II."}','berita/5.Hari Efektif','SQ8uOE_I-UEGy3LESyDsHQOSACJEHnEDFpWKKsZtn9o');
INSERT INTO "_content_search" VALUES('search/berita/ai-di-website-sekolah-dasar-teja2.md','SDN Teja 2 Resmi Integrasikan Fitur AI pada Website Resmi, Meningkatkan Pengalaman Digital Sekolah','{"type":"minimark","value":[["p",{},"Pada tanggal 15 Juli 2025, SDN Teja 2 di Rajagaluh, Majalengka, resmi meluncurkan fitur kecerdasan buatan (AI) pada website resmi mereka, ",["a",{"href":"/"},"sdnteja2.sch.id."]," Langkah ini merupakan bagian dari komitmen sekolah dalam menghadirkan pengalaman digital yang lebih interaktif dan modern bagi siswa, guru, dan orang tua."],["h2",{"id":"teknologi-yang-digunakan-dalam-integrasi-ai"},["strong",{},"Teknologi yang Digunakan dalam Integrasi AI"]],["h3",{"id":"_1-nuxthub-ai"},["strong",{},"1. NuxtHub AI"]],["p",{},"Website SDN Teja 2 dibangun menggunakan Nuxt.js, dan kini telah diintegrasikan dengan NuxtHub AI. NuxtHub AI memungkinkan pengembang untuk mengintegrasikan model pembelajaran mesin seperti Large Language Models (LLMs) ke dalam aplikasi Nuxt mereka. Dengan menggunakan API sederhana, fitur ini mendukung berbagai model untuk generasi teks, pembuatan gambar, dan embeddings. NuxtHub AI dibangun di atas Workers AI, yang memanfaatkan serverless GPUs di jaringan global Cloudflare, memastikan performa tinggi dan skalabilitas. (NuxtHub)"],["h3",{"id":"_2-workers-ai"},["strong",{},"2. Workers AI"]],["p",{},"Workers AI adalah platform yang memungkinkan eksekusi model AI secara serverless. Dengan menggunakan Cloudflare Workers, platform ini menyediakan infrastruktur untuk menjalankan model-model AI secara efisien tanpa perlu mengelola server secara manual. Hal ini memungkinkan SDN Teja 2 untuk menghadirkan fitur AI yang responsif dan skalabel kepada pengunjung website mereka.(NuxtHub)"],["h3",{"id":"_3-vercel-ai-sdk"},["strong",{},"3. Vercel AI SDK"]],["p",{},"Vercel AI SDK adalah toolkit TypeScript yang dirancang untuk membantu pengembang membangun aplikasi dan agen berbasis AI dengan framework seperti React, Next.js, Vue, Svelte, dan Node.js. SDK ini menyederhanakan integrasi model-model AI besar dengan menyediakan API yang konsisten, memungkinkan pengembang untuk fokus pada pembuatan aplikasi AI tanpa terbebani oleh detail teknis. (sdk.vercel.ai)"],["h2",{"id":"manfaat-integrasi-ai-untuk-sdn-teja-2"},["strong",{},"Manfaat Integrasi AI untuk SDN Teja 2"]],["h3",{"id":"_1-peningkatan-interaksi-pengguna"},["strong",{},"1. Peningkatan Interaksi Pengguna"]],["p",{},"Dengan adanya fitur AI, pengunjung website SDN Teja 2 kini dapat berinteraksi secara lebih dinamis. Misalnya, chatbot berbasis AI dapat menjawab pertanyaan umum tentang kegiatan sekolah, jadwal pelajaran, dan informasi lainnya, memberikan pengalaman yang lebih interaktif dan informatif."],["h3",{"id":"_2-akses-informasi-yang-lebih-cepat-dan-akurat"},["strong",{},"2. Akses Informasi yang Lebih Cepat dan Akurat"]],["p",{},"Integrasi AI memungkinkan pencarian informasi di website menjadi lebih efisien. Pengguna dapat dengan mudah menemukan materi pembelajaran, pengumuman, dan dokumen penting lainnya melalui sistem pencarian yang didukung oleh teknologi AI, mengurangi waktu yang dibutuhkan untuk mencari informasi."],["h3",{"id":"_3-dukungan-pembelajaran-yang-lebih-personal"},["strong",{},"3. Dukungan Pembelajaran yang Lebih Personal"]],["p",{},"Fitur AI dapat digunakan untuk menyediakan materi pembelajaran yang disesuaikan dengan kebutuhan masing-masing siswa. Misalnya, rekomendasi materi tambahan berdasarkan performa siswa dapat membantu dalam proses pembelajaran yang lebih personal dan efektif."],["h2",{"id":"langkah-selanjutnya-untuk-sdn-teja-2"},["strong",{},"Langkah Selanjutnya untuk SDN Teja 2"]],["p",{},"Dengan peluncuran fitur AI ini, SDN Teja 2 menunjukkan komitmennya dalam memanfaatkan teknologi untuk meningkatkan kualitas pendidikan. Ke depannya, sekolah berencana untuk terus mengembangkan dan menambah fitur-fitur berbasis AI lainnya, seperti analisis data pembelajaran dan sistem rekomendasi kegiatan ekstrakurikuler, guna mendukung perkembangan siswa secara holistik."],["h2",{"id":"faq-pertanyaan-yang-sering-diajukan"},["strong",{},"FAQ (Pertanyaan yang Sering Diajukan)"]],["p",{},["strong",{},"1. Apa itu NuxtHub AI?"]," NuxtHub AI adalah platform yang memungkinkan integrasi model AI ke dalam aplikasi Nuxt.js, memanfaatkan infrastruktur serverless untuk performa tinggi dan skalabilitas.(NuxtHub)"],["p",{},["strong",{},"2. Apa itu Workers AI?"]," Workers AI adalah platform dari Cloudflare yang memungkinkan eksekusi model AI secara serverless, menyediakan infrastruktur untuk menjalankan model-model AI tanpa perlu mengelola server secara manual."],["p",{},["strong",{},"3. Apa manfaat integrasi AI bagi SDN Teja 2?"]," Manfaatnya antara lain peningkatan interaksi pengguna, akses informasi yang lebih cepat dan akurat, serta dukungan pembelajaran yang lebih personal bagi siswa."],["p",{},["strong",{},"4. Apakah fitur AI ini dapat diakses oleh orang tua siswa?"]," Ya, orang tua siswa dapat mengakses fitur AI melalui website resmi SDN Teja 2 untuk mendapatkan informasi terkait kegiatan sekolah dan perkembangan anak mereka."],["p",{},["strong",{},"5. Apakah SDN Teja 2 berencana menambah fitur AI lainnya?"]," Ya, ke depannya SDN Teja 2 berencana untuk terus mengembangkan dan menambah fitur-fitur berbasis AI lainnya untuk mendukung kualitas pendidikan."],["p",{},["strong",{},"6. Bagaimana cara mengakses fitur AI di website SDN Teja 2?"]," Pengguna dapat mengunjungi sdnteja2.sch.id dan mulai berinteraksi dengan fitur AI yang tersedia di halaman utama."],["p",{},"Dengan langkah ini, SDN Teja 2 tidak hanya meningkatkan kualitas pengalaman digital bagi komunitas sekolah, tetapi juga menunjukkan bahwa teknologi dapat menjadi mitra dalam menciptakan lingkungan belajar yang lebih baik dan lebih efisien."]],"toc":{"title":"","searchDepth":2,"depth":2,"links":[{"id":"teknologi-yang-digunakan-dalam-integrasi-ai","depth":2,"text":"Teknologi yang Digunakan dalam Integrasi AI","children":[{"id":"_1-nuxthub-ai","depth":3,"text":"1. NuxtHub AI"},{"id":"_2-workers-ai","depth":3,"text":"2. Workers AI"},{"id":"_3-vercel-ai-sdk","depth":3,"text":"3. Vercel AI SDK"}]},{"id":"manfaat-integrasi-ai-untuk-sdn-teja-2","depth":2,"text":"Manfaat Integrasi AI untuk SDN Teja 2","children":[{"id":"_1-peningkatan-interaksi-pengguna","depth":3,"text":"1. Peningkatan Interaksi Pengguna"},{"id":"_2-akses-informasi-yang-lebih-cepat-dan-akurat","depth":3,"text":"2. Akses Informasi yang Lebih Cepat dan Akurat"},{"id":"_3-dukungan-pembelajaran-yang-lebih-personal","depth":3,"text":"3. Dukungan Pembelajaran yang Lebih Personal"}]},{"id":"langkah-selanjutnya-untuk-sdn-teja-2","depth":2,"text":"Langkah Selanjutnya untuk SDN Teja 2"},{"id":"faq-pertanyaan-yang-sering-diajukan","depth":2,"text":"FAQ (Pertanyaan yang Sering Diajukan)"}]}}','SDN Teja 2 resmi mengumumkan integrasi fitur AI pada website resmi mereka, meningkatkan pengalaman digital sekolah dengan teknologi terbaru.','md','{"date":"2025-07-15","tags":["AI","Teknologi"]}','true','/berita/ai-di-website-sekolah-dasar-teja2','{"title":"SDN Teja 2 Resmi Integrasikan Fitur AI pada Website Resmi, Meningkatkan Pengalaman Digital Sekolah","description":"SDN Teja 2 resmi mengumumkan integrasi fitur AI pada website resmi mereka, meningkatkan pengalaman digital sekolah dengan teknologi terbaru."}','berita/ai-di-website-sekolah-dasar-teja2','ge0yfq_GbZzR-NgQOWjMjEeeTUR3n4yd8KX9Vok99Dg');
