INSERT INTO "_content_guru" VALUES('guru/guru/8.putriana-indrawati.yml','Putriana Indrawati','{"nama":"Putriana Indrawati","lengkap":"Putriana Indrawati, S.Pd.","catatan":"Ilmu adalah harta, dan guru adalah kunci pembukanya.","kelas":"Guru PAI","foto":"https://res.cloudinary.com/dyy24w5kl/image/upload/v1729924570/guru/putri.jpg","jabatan":"Pembina Keagamaan","pendidikan":"S1 - PAI"}','Ilmu adalah harta, dan guru adalah kunci pembukanya.',NULL,'yml','https://res.cloudinary.com/dyy24w5kl/image/upload/v1729924570/guru/putri.jpg','Pembina Keagamaan','Guru PAI','Putriana Indrawati, S.Pd.','{}','Putriana Indrawati','true','/guru/putriana-indrawati',NULL,'S1 - PAI','{"title":"Putriana Indrawati"}',NULL,'guru/8.putriana-indrawati','WxS5H-ILvNVspBfl2TMyvXaH-FhcUNI2j2QwpLPNaZs');
INSERT INTO "_content_artikel" VALUES('artikel/artikel/1.sejarah pendidilan.md','Sejarah Pendidikan di Indonesia: Perkembangan dan Transformasi dari Masa ke Masa','Dinar Permadi','{"type":"minimark","value":[["p",{},"Sejarah pendidikan di Indonesia mencakup perkembangan dari sistem tradisional hingga era modern. Artikel ini mengulas perjalanan pendidikan Indonesia dari masa kerajaan, penjajahan Belanda, pendudukan Jepang, hingga pasca kemerdekaan, serta tantangan dan harapan di masa depan."],["p",{},"Pendidikan di Indonesia memiliki perjalanan yang panjang dan penuh tantangan, dipengaruhi oleh berbagai faktor sejarah, politik, dan sosial budaya. Sejarah pendidikan di Indonesia dimulai jauh sebelum masa penjajahan, dengan sistem pendidikan tradisional yang telah ada di masyarakat. Namun, pengaruh luar, baik dari bangsa Eropa maupun penjajahan, memainkan peran yang besar dalam pembentukan sistem pendidikan seperti yang kita kenal sekarang."],["h2",{"id":"pendidikan-pada-masa-kerajaan"},"Pendidikan pada Masa Kerajaan"],["p",{},"Sebelum kedatangan bangsa Eropa, pendidikan di Indonesia lebih bersifat informal dan tradisional, mencerminkan kearifan lokal yang telah berkembang selama berabad-abad. Masyarakat adat memiliki sistem pengajaran yang unik, di mana pengetahuan diwariskan secara turun-temurun melalui proses belajar mengajar yang terintegrasi dalam kehidupan sehari-hari. Proses pembelajaran ini tidak terbatas pada ruang kelas formal, melainkan berlangsung dalam berbagai konteks sosial dan budaya, seperti di ladang, hutan, pantai, atau dalam upacara-upacara adat. Pengetahuan yang diajarkan mencakup spektrum yang luas, meliputi keterampilan praktis seperti pertanian dan perdagangan, serta aspek-aspek kehidupan yang lebih abstrak seperti seni, nilai-nilai budaya, dan ajaran agama. Metode pengajaran ini memungkinkan transfer pengetahuan yang holistik, memadukan teori dan praktik dalam satu kesatuan yang utuh."],["p",{},["img",{"alt":"New image","src":"https://res.cloudinary.com/dyy24w5kl/image/upload/v1732023188/artikel/artikel_sejarah_pendidikanfreepik__adorable-cartoon-style-education-in-the-era-of-the__62008_xe3op3.jpg"}]],["p",{},"Di kerajaan-kerajaan besar seperti Majapahit dan Sriwijaya, pendidikan memiliki posisi yang sangat penting dalam struktur sosial dan pemerintahan. Kedua kerajaan ini, yang merupakan pusat peradaban di Nusantara pada masanya, mengembangkan sistem pendidikan yang lebih terstruktur, meskipun masih bersifat eksklusif. Pendidikan agama Hindu-Buddha menjadi landasan filosofis, sementara ilmu pengetahuan dalam bidang astronomi, matematika, dan sastra dikembangkan sebagai pilar intelektual kerajaan. Astronomi digunakan untuk menentukan musim tanam dan pelayaran, matematika untuk arsitektur dan perdagangan, sementara sastra menjadi media untuk melestarikan sejarah dan nilai-nilai budaya. Pada masa ini, pendidikan formal sering kali menjadi privilese golongan bangsawan atau mereka yang berada dalam lingkup istana, menciptakan elit intelektual yang berperan penting dalam pemerintahan dan diplomasi. Meskipun demikian, pengetahuan ini tidak sepenuhnya terisolasi, karena ada mekanisme penyebaran ilmu melalui pesantren, padepokan, dan lembaga pendidikan tradisional lainnya yang lebih terbuka untuk masyarakat umum. Sistem pendidikan di kerajaan-kerajaan tersebut masih sangat terkait erat dengan kehidupan kerajaan dan budaya yang berkembang, mencerminkan kompleksitas struktur sosial dan politik pada masa itu."],["h2",{"id":"pendidikan-pada-masa-penjajahan-belanda"},"Pendidikan pada Masa Penjajahan Belanda"],["p",{},"Pada masa penjajahan Belanda, yang berlangsung dari awal abad ke-17 hingga tahun 1942, sistem pendidikan di Indonesia mengalami perubahan yang signifikan dan transformatif. Pemerintah kolonial Belanda memperkenalkan sistem pendidikan yang lebih terstruktur dan formal, menggantikan sistem pendidikan tradisional yang telah ada sebelumnya. Meskipun demikian, sistem pendidikan yang dibawa oleh Belanda ini memiliki karakteristik yang sangat diskriminatif, mencerminkan hierarki sosial dan rasial yang ada pada masa itu. Tujuan utama dari sistem pendidikan ini bukanlah untuk mencerdaskan kehidupan bangsa Indonesia, melainkan lebih ditujukan"]],"toc":{"title":"","searchDepth":2,"depth":2,"links":[{"id":"pendidikan-pada-masa-kerajaan","depth":2,"text":"Pendidikan pada Masa Kerajaan"},{"id":"pendidikan-pada-masa-penjajahan-belanda","depth":2,"text":"Pendidikan pada Masa Penjajahan Belanda"}]}}','2024-11-19T00:00:00.000Z','Sejarah pendidikan di Indonesia mencakup perkembangan dari sistem tradisional hingga era modern. Artikel ini mengulas perjalanan pendidikan Indonesia dari masa kerajaan, penjajahan Belanda, pendudukan Jepang, hingga pasca kemerdekaan, serta tantangan dan harapan di masa depan.','md','https://res.cloudinary.com/dyy24w5kl/image/upload/v1732023187/artikel/artikel_sejarah_pendidikanfreepik__adorable-cartoon-style-indonesian-education-after-__62014_fye57v.jpg','{}','true','/artikel/sejarah-pendidilan','{"title":"Sejarah Pendidikan di Indonesia: Perkembangan dan Transformasi dari Masa ke Masa","description":"Sejarah pendidikan di Indonesia mencakup perkembangan dari sistem tradisional hingga era modern. Artikel ini mengulas perjalanan pendidikan Indonesia dari masa kerajaan, penjajahan Belanda, pendudukan Jepang, hingga pasca kemerdekaan, serta tantangan dan harapan di masa depan."}','artikel/1.sejarah pendidilan','["Sejarah","Pendidikan"]','sT-V5qWwg3VsBowa-6QMX4OFHOj9MDAQ_OmJokWD0CM');
INSERT INTO "_content_artikel" VALUES('artikel/artikel/2.raport-pendidikan.md','Rapor Pendidikan: Pengertian, Fungsi, dan Manfaat dalam Peningkatan Mutu Sekolah','Dinar Permadi','{"type":"minimark","value":[["p",{},"Rapor pendidikan adalah salah satu instrumen evaluasi bagi sekolah dan pemerintah dalam memantau perkembangan dan mutu pendidikan di berbagai jenjang. Artikel ini akan membahas mengenai definisi, fungsi, manfaat, serta bagaimana rapor pendidikan digunakan. Selain itu, akan dijelaskan peran Asesmen Nasional Berbasis Komputer (ANBK) dalam menyediakan data untuk rapor pendidikan, serta berbagai informasi yang dapat diperoleh dari laporan ini untuk pengambilan keputusan."],["h2",{"id":"apa-itu-rapor-pendidikan"},"Apa Itu Rapor Pendidikan?"],["p",{},"Rapor pendidikan adalah sistem laporan berbasis data yang memuat informasi tentang capaian pendidikan sekolah, seperti kualitas hasil belajar, lingkungan belajar, dan efektivitas manajemen sekolah. Rapor ini digunakan oleh pemerintah dan sekolah untuk melihat aspek-aspek yang masih perlu ditingkatkan."],["h2",{"id":"fungsi-dan-manfaat-rapor-pendidikan"},"Fungsi dan Manfaat Rapor Pendidikan"],["p",{},"Rapor pendidikan berfungsi sebagai alat evaluasi yang objektif dan akurat untuk mengetahui capaian mutu pendidikan. Berikut manfaatnya:"],["ul",{},["li",{},["strong",{},"Meningkatkan Kualitas Pembelajaran:"]," Sekolah dapat mengetahui area yang memerlukan perbaikan."],["li",{},["strong",{},"Dasar Pengambilan Keputusan:"]," Pemerintah dan sekolah dapat membuat kebijakan berbasis data."],["li",{},["strong",{},"Memantau Perkembangan Sekolah:"]," Setiap tahun, rapor pendidikan memberikan gambaran apakah sekolah mengalami peningkatan mutu atau tidak."],["li",{},["strong",{},"Transparansi Publik:"]," Informasi mutu sekolah dapat diakses sebagai bentuk akuntabilitas pendidikan."]],["h2",{"id":"apa-itu-rapor-mutu-pendidikan"},"Apa Itu Rapor Mutu Pendidikan?"],["p",{},"Rapor mutu pendidikan adalah bagian dari rapor pendidikan yang lebih fokus pada aspek kualitas dan efektivitas sekolah, termasuk komponen proses pembelajaran, kualitas guru, dan manajemen sekolah. Ini merupakan bagian penting untuk melihat apakah standar nasional pendidikan sudah terpenuhi atau belum."],["h2",{"id":"masuk-rapor-pendidikan-menggunakan-akun-apa"},"Masuk Rapor Pendidikan Menggunakan Akun Apa?"],["p",{},"Untuk mengakses rapor pendidikan, pengguna (kepala sekolah atau admin) harus menggunakan akun ",["strong",{},"Dapodik"]," atau ",["strong",{},"akun dinas pendidikan"]," terkait. Akun ini telah terintegrasi dengan data sekolah yang ada di pusat, sehingga akses hanya diberikan kepada pihak-pihak yang berwenang."],["h2",{"id":"kapan-rapor-pendidikan-dapat-digunakan"},"Kapan Rapor Pendidikan Dapat Digunakan?"],["p",{},"Rapor pendidikan dapat diakses dan dimanfaatkan setelah ",["strong",{},"Asesmen Nasional Berbasis Komputer (ANBK)"]," dan evaluasi tahunan selesai. Biasanya, rapor ini tersedia pada awal tahun berikutnya setelah data ANBK dan hasil pemetaan disusun."],["h2",{"id":"untuk-apa-hasil-anbk"},"Untuk Apa Hasil ANBK?"],["p",{},["img",{"alt":"ANBK","src":"https://res.cloudinary.com/dyy24w5kl/image/upload/v1730100640/artikel/ujian1_dkq4xb.png","height":900,"width":1600}]],["p",{},"Hasil ANBK digunakan untuk memetakan capaian kompetensi siswa dan kondisi sekolah secara keseluruhan. Informasi ini menjadi dasar bagi:"],["ul",{},["li",{},"Perbaikan kurikulum dan proses belajar mengajar."],["li",{},"Penyusunan program peningkatan mutu sekolah."],["li",{},"Evaluasi kebijakan pendidikan nasional dan daerah."],["li",{},"Memonitor ketimpangan pendidikan di berbagai wilayah."]],["h2",{"id":"informasi-apa-yang-dapat-diambil-dari-rapor-pendidikan"},"Informasi Apa yang Dapat Diambil dari Rapor Pendidikan?"],["p",{},["img",{"alt":"Raport Pendidikan","src":"https://res.cloudinary.com/dyy24w5kl/image/upload/v1730100644/artikel/MQZCZrqlzK_mjx360.png"}]],["p",{},"Rapor pendidikan berisi beberapa poin penting seperti:"],["ul",{},["li",{},["strong",{},"Capaian Kompetensi Dasar:"]," Seperti kemampuan literasi dan numerasi siswa."],["li",{},["strong",{},"Kondisi Lingkungan Sekolah:"]," Tingkat keamanan dan kenyamanan."],["li",{},["strong",{},"Kualitas Guru:"]," Tingkat profesionalisme dan kinerja guru."],["li",{},["strong",{},"Partisipasi Siswa dan Orang Tua:"]," Tingkat keterlibatan dalam pembelajaran."],["li",{},["strong",{},"Manajemen dan Kepemimpinan Sekolah:"]," Efektivitas pengelolaan sekolah."]],["h2",{"id":"kesimpulan"},"Kesimpulan"],["p",{},"Rapor pendidikan dan rapor mutu pendidikan merupakan alat penting untuk memastikan bahwa setiap sekolah mencapai standar yang diharapkan. Dengan adanya rapor ini, sekolah, pemerintah, dan pemangku kepentingan lainnya dapat bekerja sama untuk meningkatkan mutu pendidikan di Indonesia. Hasil ANBK berperan penting dalam mendukung evaluasi dan perencanaan pendidikan yang lebih baik."]],"toc":{"title":"","searchDepth":2,"depth":2,"links":[{"id":"apa-itu-rapor-pendidikan","depth":2,"text":"Apa Itu Rapor Pendidikan?"},{"id":"fungsi-dan-manfaat-rapor-pendidikan","depth":2,"text":"Fungsi dan Manfaat Rapor Pendidikan"},{"id":"apa-itu-rapor-mutu-pendidikan","depth":2,"text":"Apa Itu Rapor Mutu Pendidikan?"},{"id":"masuk-rapor-pendidikan-menggunakan-akun-apa","depth":2,"text":"Masuk Rapor Pendidikan Menggunakan Akun Apa?"},{"id":"kapan-rapor-pendidikan-dapat-digunakan","depth":2,"text":"Kapan Rapor Pendidikan Dapat Digunakan?"},{"id":"untuk-apa-hasil-anbk","depth":2,"text":"Untuk Apa Hasil ANBK?"},{"id":"informasi-apa-yang-dapat-diambil-dari-rapor-pendidikan","depth":2,"text":"Informasi Apa yang Dapat Diambil dari Rapor Pendidikan?"},{"id":"kesimpulan","depth":2,"text":"Kesimpulan"}]}}','2024-10-28T00:00:00.000Z','Rapor pendidikan adalah salah satu instrumen evaluasi bagi sekolah dan pemerintah dalam memantau perkembangan dan mutu pendidikan di berbagai jenjang.','md','https://res.cloudinary.com/dyy24w5kl/image/upload/v1730100651/artikel/BUeNWYemFS_v3ynrq.png','{}','true','/artikel/raport-pendidikan','{"title":"Rapor Pendidikan: Pengertian, Fungsi, dan Manfaat dalam Peningkatan Mutu Sekolah","description":"Rapor pendidikan adalah salah satu instrumen evaluasi bagi sekolah dan pemerintah dalam memantau perkembangan dan mutu pendidikan di berbagai jenjang."}','artikel/2.raport-pendidikan','["Guru","Raport Mutu"]','gs0c9eOW89v_lwbEPipSZ8WrxsoY_j5Nux2Z_h_12TE');
INSERT INTO "_content_artikel" VALUES('artikel/artikel/3.penerimaan-peserta-didik-baru.md','PPDB SD 2025: Sistem, Syarat, Jadwal, dan Prosedur Terbaru','Dinar Permadi','{"type":"minimark","value":[["p",{},"Penerimaan Peserta Didik Baru (PPDB) untuk jenjang Sekolah Dasar (SD) tahun 2025 mengalami perubahan signifikan. Pemerintah resmi mengganti istilah PPDB menjadi Sistem Penerimaan Murid Baru (SPMB) mulai tahun ajaran 2025/2026. Berikut ulasan lengkap mengenai SPMB SD 2025, mulai dari syarat, jalur pendaftaran, jadwal, hingga dokumen yang perlu disiapkan."],["h2",{"id":"perubahan-sistem-ppdb-menjadi-spmb"},["strong",{},"Perubahan Sistem: PPDB Menjadi SPMB"]],["p",{},"Mulai tahun 2025, proses penerimaan siswa baru di seluruh Indonesia tidak lagi menggunakan istilah PPDB, melainkan SPMB (Sistem Penerimaan Murid Baru). Pergantian ini diatur dalam Permendikdasmen No 3 Tahun 2025 dan bertujuan untuk meningkatkan transparansi, keadilan, serta kemudahan akses pendaftaran melalui sistem online di semua jenjang pendidikan, termasuk SD."],["h2",{"id":"jalur-pendaftaran-spmb-sd-2025"},["strong",{},"Jalur Pendaftaran SPMB SD 2025"]],["p",{},"Terdapat tiga jalur utama dalam SPMB SD 2025 yang menggantikan sistem zonasi pada PPDB sebelumnya124:"],["ul",{},["li",{},["strong",{},"Jalur Domisili (Zonasi):"]," Untuk anak yang berdomisili di sekitar wilayah sekolah. Dibuktikan dengan Kartu Keluarga (KK) yang sudah diterbitkan minimal 1 tahun sebelum pendaftaran."],["li",{},["strong",{},"Jalur Afirmasi:"]," Diperuntukkan bagi anak dari keluarga kurang mampu, penyandang disabilitas, atau kelompok rentan lainnya. Bukti berupa KIP, KKS, atau surat keterangan disabilitas."],["li",{},["strong",{},"Jalur Mutasi:"]," Untuk anak yang mengikuti perpindahan orang tua/guru karena tugas. Bukti berupa surat tugas, surat pindah domisili, dan KK terbaru."]],["h2",{"id":"syarat-umum-dan-khusus-masuk-sd-2025"},["strong",{},"Syarat Umum dan Khusus Masuk SD 2025"]],["p",{},["strong",{},"Syarat usia dan dokumen penting yang wajib dipenuhi calon peserta didik SD tahun 2025 adalah sebagai berikut:"]],["ul",{},["li",{},["strong",{},"Usia Minimal:"],["ul",{},["li",{},"Usia 7 tahun per 1 Juli 2025 diprioritaskan diterima."],["li",{},"Usia minimal 6 tahun per 1 Juli 2025 diperbolehkan mendaftar."],["li",{},"Usia minimal 5 tahun 6 bulan per 1 Juli 2025 dapat mendaftar jika memiliki kecerdasan dan/atau bakat istimewa serta kesiapan psikis, dibuktikan dengan rekomendasi tertulis dari psikolog profesional atau dewan guru jika psikolog tidak tersedia."]]],["li",{},["strong",{},"Dokumen Wajib:"],["ul",{},["li",{},"Akta kelahiran atau surat keterangan lahir yang dilegalisasi pejabat berwenang."],["li",{},"Kartu Keluarga (KK) yang diterbitkan minimal 1 tahun sebelum pendaftaran."],["li",{},"Pas foto terbaru calon siswa."],["li",{},"Ijazah TK atau Surat Keterangan Lulus (jika ada)."]]],["li",{},["strong",{},"Khusus Penyandang Disabilitas atau Daerah 3T:"]," Syarat usia dapat dikecualikan untuk anak penyandang disabilitas, SD layanan khusus (SDLB), dan SD di daerah tertinggal, terdepan, dan terluar (3T)."],["li",{},["strong",{},"Tidak Ada Tes Calistung:"]," Seleksi masuk SD tidak boleh menggunakan tes membaca, menulis, dan berhitung (calistung)."]],["h2",{"id":"jadwal-pendaftaran-spmb-sd-2025"},["strong",{},"Jadwal Pendaftaran SPMB SD 2025"]],["p",{},"Jadwal pendaftaran SPMB SD tahun 2025 umumnya berlangsung mulai awal Mei hingga Juli 2025. Namun, jadwal pasti bisa berbeda di tiap daerah sesuai kebijakan pemerintah daerah masing-masing."],["p",{},"Berikut gambaran umum tahapan SPMB SD 2025:"],["ul",{},["li",{},["strong",{},"Penetapan Wilayah & Kuota:"]," Maret 2025"],["li",{},["strong",{},"Pengumuman Pendaftaran:"]," Minggu pertama Mei 2025"],["li",{},["strong",{},"Pendaftaran Jalur Afirmasi & Mutasi:"]," Awal hingga pertengahan Juni 2025"],["li",{},["strong",{},"Pendaftaran Jalur Domisili:"]," Pertengahan hingga akhir Juni 2025"],["li",{},["strong",{},"Seleksi & Pengumuman Hasil:"]," Sesuai kebijakan sekolah masing-masing"],["li",{},["strong",{},"Integrasi Data Murid Baru:"]," Agustus 2025."]],["h2",{"id":"prosedur-pendaftaran-online"},["strong",{},"Prosedur Pendaftaran Online"]],["p",{},"SPMB SD 2025 dilakukan secara daring melalui portal resmi SPMB di setiap provinsi atau kabupaten/kota. Calon peserta didik atau orang tua wajib membuat akun, mengunggah dokumen persyaratan, memilih jalur pendaftaran, dan memilih sekolah tujuan sesuai domisili atau jalur yang diambil."],["p",{},["img",{"alt":"ppdb","src":"/artikel/ppdb.png"}]],["h2",{"id":"tips-dan-catatan-penting"},["strong",{},"Tips dan Catatan Penting"]],["ul",{},["li",{},"Selalu pantau pengumuman resmi dari Dinas Pendidikan setempat dan website SPMB daerah Anda."],["li",{},"Pastikan semua dokumen asli dan fotokopi telah disiapkan serta dilegalisasi sesuai ketentuan."],["li",{},"Jika terjadi perubahan data pada KK kurang dari 1 tahun, pastikan perubahan tersebut sesuai dengan ketentuan yang berlaku, seperti penambahan anggota keluarga atau pengurangan akibat meninggal dunia/pindah."]],["h2",{"id":"kesimpulan"},["strong",{},"Kesimpulan"]],["p",{},"Sistem penerimaan siswa baru SD tahun 2025 kini lebih transparan, mudah, dan inklusif melalui SPMB. Orang tua dan calon peserta didik wajib memahami syarat, jalur, serta jadwal pendaftaran agar proses berjalan lancar. Pastikan selalu mengikuti informasi resmi dari instansi pendidikan terkait untuk menghindari kesalahan saat mendaftar."]],"toc":{"title":"","searchDepth":2,"depth":2,"links":[{"id":"perubahan-sistem-ppdb-menjadi-spmb","depth":2,"text":"Perubahan Sistem: PPDB Menjadi SPMB"},{"id":"jalur-pendaftaran-spmb-sd-2025","depth":2,"text":"Jalur Pendaftaran SPMB SD 2025"},{"id":"syarat-umum-dan-khusus-masuk-sd-2025","depth":2,"text":"Syarat Umum dan Khusus Masuk SD 2025"},{"id":"jadwal-pendaftaran-spmb-sd-2025","depth":2,"text":"Jadwal Pendaftaran SPMB SD 2025"},{"id":"prosedur-pendaftaran-online","depth":2,"text":"Prosedur Pendaftaran Online"},{"id":"tips-dan-catatan-penting","depth":2,"text":"Tips dan Catatan Penting"},{"id":"kesimpulan","depth":2,"text":"Kesimpulan"}]}}','2025-06-22T00:00:00.000Z','Penerimaan Peserta Didik Baru (PPDB) untuk jenjang Sekolah Dasar (SD) tahun 2025 mengalami perubahan signifikan. Pemerintah resmi mengganti istilah PPDB menjadi Sistem Penerimaan Murid Baru (SPMB) mulai tahun ajaran 2025/2026. Berikut ulasan lengkap mengenai SPMB SD 2025, mulai dari syarat, jalur pendaftaran, jadwal, hingga dokumen yang perlu disiapkan.','md','https://res.cloudinary.com/dyy24w5kl/image/upload/v1752354397/artikel/artikel-ppdb_xwnmne.png','{}','true','/artikel/penerimaan-peserta-didik-baru','{"title":"PPDB SD 2025: Sistem, Syarat, Jadwal, dan Prosedur Terbaru","description":"Penerimaan Peserta Didik Baru (PPDB) untuk jenjang Sekolah Dasar (SD) tahun 2025 mengalami perubahan signifikan. Pemerintah resmi mengganti istilah PPDB menjadi Sistem Penerimaan Murid Baru (SPMB) mulai tahun ajaran 2025/2026. Berikut ulasan lengkap mengenai SPMB SD 2025, mulai dari syarat, jalur pendaftaran, jadwal, hingga dokumen yang perlu disiapkan."}','artikel/3.penerimaan-peserta-didik-baru','["Guru","PPDB","Siswa"]','NuVz8EjiP8ZbTP-jkXM8MQTrG8I-P0ZoaZJiwNHhnAg');
INSERT INTO "_content_artikel" VALUES('artikel/artikel/4.sejarah-jambore-ranting-di-indonesia-10-fakta-menarik.md','Sejarah Jambore Ranting di Indonesia: 10 Fakta Menarik yang Perlu Anda Ketahui','Dinar Permadi','{"type":"minimark","value":[["p",{},"Kegiatan ini bukan hanya ajang pertemuan biasa, tetapi juga mengandung nilai-nilai sejarah dan edukasi yang penting untuk dipahami oleh setiap anggota Pramuka di Indonesia. Melalui artikel ini, kita akan menggali lebih dalam mengenai sejarah, tujuan, manfaat, serta perkembangan Jambore Ranting di Indonesia hingga kini."],["h2",{"id":"definisi-dan-tujuan-jambore-ranting"},["strong",{},"Definisi dan Tujuan Jambore Ranting"]],["p",{},["strong",{},"Jambore Ranting"]," adalah kegiatan perkemahan besar yang dilakukan di tingkat kecamatan (ranting), yang melibatkan berbagai Gugus Depan (Gudep) Pramuka dari tingkat Siaga, Penggalang, hingga Penegak. Secara umum, tujuan utama dari Jambore Ranting adalah menciptakan wadah pertemuan antar anggota Pramuka untuk berbagi pengalaman, meningkatkan keterampilan, serta menguatkan rasa kebersamaan dan persaudaraan."],["p",{},"Kegiatan ini menjadi titik awal penting dalam melatih anggota Pramuka agar menjadi lebih mandiri, kreatif, dan bertanggung jawab, sejalan dengan prinsip dasar dan metode pendidikan kepramukaan. Dalam setiap penyelenggaraannya, kegiatan ini juga menitikberatkan pada pentingnya kerja tim, disiplin, dan jiwa nasionalisme, sehingga mampu memberikan dampak positif terhadap perkembangan karakter generasi muda Indonesia."],["h2",{"id":"sejarah-awal-jambore-ranting-di-indonesia"},["strong",{},"Sejarah Awal Jambore Ranting di Indonesia"]],["h3",{"id":"latar-belakang-munculnya-jambore-ranting"},["strong",{},"Latar Belakang Munculnya Jambore Ranting"]],["p",{},"Sejarah Jambore Ranting di Indonesia dimulai tak lama setelah Gerakan Pramuka secara resmi berdiri pada tahun 1961. Pada masa itu, pemerintah Indonesia tengah giat membangun karakter generasi muda melalui berbagai kegiatan kepanduan yang dikoordinasikan oleh Gerakan Pramuka. Jambore Ranting hadir sebagai solusi untuk menjangkau lebih banyak anak muda di berbagai daerah, terutama di wilayah kecamatan yang sulit mengakses kegiatan berskala besar."],["h3",{"id":"tahun-pertama-penyelenggaraan"},["strong",{},"Tahun Pertama Penyelenggaraan"]],["p",{},"Penyelenggaraan pertama Jambore Ranting tercatat dimulai pada pertengahan tahun 1960-an. Kegiatan tersebut awalnya dilakukan secara sederhana dengan peserta terbatas, namun terus berkembang pesat karena tingginya antusiasme masyarakat."],["h3",{"id":"daerah-pertama-yang-mengadakan-jambore-ranting"},["strong",{},"Daerah Pertama yang Mengadakan Jambore Ranting"]],["p",{},"Daerah yang pertama kali mencetuskan pelaksanaan Jambore Ranting secara terstruktur adalah Jawa Tengah, tepatnya di daerah sekitar Semarang. Dari Jawa Tengah, konsep Jambore Ranting kemudian menyebar cepat ke daerah-daerah lain seperti Jawa Timur, Jawa Barat, hingga akhirnya menyebar ke seluruh Indonesia."],["h2",{"id":"perkembangan-jambore-ranting-dari-masa-ke-masa"},["strong",{},"Perkembangan Jambore Ranting dari Masa ke Masa"]],["p",{},["img",{"alt":"Jambore","src":"/artikel/jambore-1.png"}]],["h3",{"id":"era-1960-an-hingga-1980-an"},["strong",{},"Era 1960-an hingga 1980-an"]],["p",{},"Pada era ini, Jambore Ranting mulai berkembang signifikan. Dengan dukungan penuh pemerintah pusat, terutama Kementerian Pendidikan dan Kebudayaan, Jambore Ranting berhasil digelar secara rutin di berbagai wilayah Indonesia. Di masa tersebut, kegiatan lebih terfokus pada pendidikan karakter, keterampilan dasar kepramukaan seperti membuat simpul, tanda jejak, dan bertahan di alam terbuka. Selain itu, para peserta juga diajarkan nilai-nilai kedisiplinan dan nasionalisme melalui kegiatan seperti upacara bendera dan latihan baris-berbaris."],["h3",{"id":"transformasi-di-era-reformasi"},["strong",{},"Transformasi di Era Reformasi"]],["p",{},"Era Reformasi (1998-2000-an) membawa perubahan besar terhadap Jambore Ranting. Saat ini, aktivitas kepramukaan mulai lebih terbuka, inovatif, dan inklusif. Penyelenggaraannya tidak lagi didominasi oleh kegiatan kepanduan konvensional, tetapi mulai mengadopsi kegiatan sosial, lingkungan, dan bahkan teknologi. Di masa ini pula Jambore Ranting semakin mendapatkan perhatian publik, menjadi agenda rutin yang didukung oleh komunitas dan pemerintah daerah secara lebih aktif."],["h3",{"id":"adaptasi-di-era-digital"},["strong",{},"Adaptasi di Era Digital"]],["p",{},"Memasuki era digital, Jambore Ranting turut beradaptasi dengan perkembangan teknologi. Kini, kegiatan tersebut tidak hanya berfokus pada keterampilan kepanduan tradisional, tetapi juga menggabungkan kegiatan berbasis teknologi seperti workshop fotografi, pelatihan penggunaan media sosial positif, hingga pemanfaatan teknologi ramah lingkungan seperti energi surya dan hidroponik."],["h2",{"id":"struktur-organisasi-jambore-ranting"},["strong",{},"Struktur Organisasi Jambore Ranting"]],["p",{},["img",{"alt":"Jambore","src":"/artikel/jambore-2.png"}]],["h3",{"id":"tugas-dan-fungsi-panitia-jambore-ranting"},["strong",{},"Tugas dan Fungsi Panitia Jambore Ranting"]],["p",{},"Penyelenggaraan Jambore Ranting melibatkan struktur organisasi yang jelas dan teratur. Panitia Jambore Ranting biasanya terdiri dari Pembina Pramuka, para guru, tokoh masyarakat, hingga perwakilan Gugus Depan. Panitia bertugas memastikan seluruh kegiatan berlangsung lancar, mulai dari persiapan hingga penutupan acara. Mereka juga bertanggung jawab terhadap keamanan, logistik, kesehatan, hingga keberlangsungan seluruh kegiatan yang dilakukan selama jambore berlangsung."],["h3",{"id":"peran-gugus-depan-dalam-jambore-ranting"},["strong",{},"Peran Gugus Depan dalam Jambore Ranting"]],["p",{},"Gugus Depan (Gudep) adalah bagian penting dalam pelaksanaan Jambore Ranting, sebab merekalah yang membawa peserta untuk mengikuti kegiatan ini. Gudep bertugas melakukan pembinaan, pelatihan, serta memberikan bekal materi yang diperlukan peserta. Dalam jambore, setiap Gudep juga menampilkan kreativitasnya melalui pementasan seni, kegiatan keterampilan, hingga inovasi-inovasi menarik lainnya."],["h2",{"id":"tujuan-dan-manfaat-pelaksanaan-jambore-ranting"},["strong",{},"Tujuan dan Manfaat Pelaksanaan Jambore Ranting"]],["h3",{"id":"pembentukan-karakter-anggota-pramuka"},["strong",{},"Pembentukan Karakter Anggota Pramuka"]],["p",{},"Tujuan utama dari Jambore Ranting adalah membentuk karakter peserta yang tangguh, mandiri, bertanggung jawab, serta berjiwa sosial tinggi. Melalui kegiatan berkemah dan berbagai tantangan di alam terbuka, peserta belajar untuk bekerja sama, menghargai perbedaan, dan memahami pentingnya nilai-nilai moral dan etika."],["h3",{"id":"menumbuhkan-jiwa-nasionalisme"},["strong",{},"Menumbuhkan Jiwa Nasionalisme"]],["p",{},"Nasionalisme merupakan salah satu nilai penting yang selalu ditekankan dalam setiap kegiatan Jambore Ranting. Peserta dibiasakan untuk mencintai tanah airnya melalui berbagai kegiatan seperti upacara bendera, lagu kebangsaan, dan pemahaman sejarah bangsa. Kegiatan ini secara tidak langsung memperkuat rasa cinta tanah air dan kebanggaan terhadap identitas bangsa Indonesia."],["h3",{"id":"meningkatkan-kemandirian-dan-kepemimpinan"},["strong",{},"Meningkatkan Kemandirian dan Kepemimpinan"]],["p",{},"Peserta diajak mengasah kemampuan kemandirian dan kepemimpinan sejak dini. Mereka diberi kesempatan untuk memimpin kelompok, menyelesaikan tantangan, serta memecahkan berbagai masalah secara kreatif dan inovatif. Keterampilan ini sangat bermanfaat untuk masa depan mereka sebagai calon pemimpin bangsa."],["h2",{"id":"aktivitas-yang-dilakukan-dalam-jambore-ranting"},["strong",{},"Aktivitas yang Dilakukan dalam Jambore Ranting"]],["h3",{"id":"kegiatan-kepanduan-tradisional"},["strong",{},"Kegiatan Kepanduan Tradisional"]],["p",{},"Kegiatan tradisional yang dilakukan di Jambore Ranting meliputi pionering, membuat tenda, semaphore, dan morse. Kegiatan tersebut bertujuan agar peserta memahami dasar-dasar kepanduan dengan baik."],["h3",{"id":"kegiatan-keagamaan-dan-sosial"},["strong",{},"Kegiatan Keagamaan dan Sosial"]],["p",{},"Jambore Ranting juga dilengkapi kegiatan keagamaan yang mengajarkan peserta untuk toleran dan menghargai perbedaan agama. Kegiatan sosial seperti bakti masyarakat, penghijauan, dan kebersihan lingkungan juga sering diadakan."],["h3",{"id":"kegiatan-olahraga-dan-permainan-tradisional"},["strong",{},"Kegiatan Olahraga dan Permainan Tradisional"]],["p",{},"Untuk menambah keseruan, peserta diajak untuk berpartisipasi dalam olahraga tradisional seperti tarik tambang, balap karung, panjat pinang, dan berbagai permainan lainnya yang melatih kebugaran, kekompakan, dan strategi."],["h2",{"id":"tokoh-penting-dalam-sejarah-jambore-ranting"},["strong",{},"Tokoh Penting dalam Sejarah Jambore Ranting"]],["h3",{"id":"pelopor-awal-dan-tokoh-inspiratif"},["strong",{},"Pelopor Awal dan Tokoh Inspiratif"]],["p",{},"Sejarah Jambore Ranting tidak terlepas dari peran sejumlah tokoh penting, salah satunya Sri Sultan Hamengkubuwono IX, yang dikenal sebagai Bapak Pramuka Indonesia. Beliau adalah tokoh yang secara aktif mendorong berkembangnya kegiatan kepanduan, termasuk jambore di tingkat ranting. Kepemimpinannya dalam Gerakan Pramuka memberikan inspirasi besar bagi pelaksanaan kegiatan Jambore Ranting secara rutin di seluruh Indonesia."],["p",{},"Selain Sri Sultan Hamengkubuwono IX, terdapat pula tokoh seperti Kak Agus Salim, yang juga memiliki peran besar dalam pembentukan karakter kepanduan. Kegiatan kepramukaan yang diselenggarakan di tingkat ranting sering kali merujuk pada prinsip dan ajaran beliau tentang nasionalisme, toleransi, dan kedisiplinan."],["h3",{"id":"kontribusi-tokoh-tokoh-pramuka-terkenal"},["strong",{},"Kontribusi Tokoh-tokoh Pramuka Terkenal"]],["p",{},"Di era modern, nama-nama seperti Kak Adhyaksa Dault (mantan Ketua Kwartir Nasional Pramuka), Kak Budi Waseso (Ketua Kwartir Nasional saat ini), serta tokoh lokal seperti para Ketua Kwartir Daerah turut berperan besar dalam memajukan Jambore Ranting. Mereka aktif memberikan dukungan moral, finansial, dan kebijakan yang semakin memperkuat keberadaan kegiatan ini di berbagai daerah."],["h2",{"id":"dampak-jambore-ranting-terhadap-komunitas-lokal"},["strong",{},"Dampak Jambore Ranting terhadap Komunitas Lokal"]],["h3",{"id":"dampak-sosial-dan-ekonomi"},["strong",{},"Dampak Sosial dan Ekonomi"]],["p",{},"Pelaksanaan Jambore Ranting sering memberikan dampak positif bagi komunitas lokal di sekitarnya. Secara sosial, kegiatan ini meningkatkan kesadaran dan solidaritas masyarakat, terutama dalam hal gotong royong dan rasa saling membantu. Dari sisi ekonomi, Jambore Ranting bisa menjadi peluang bisnis bagi masyarakat sekitar, seperti penjualan makanan, minuman, dan kerajinan lokal."],["h3",{"id":"pengaruh-terhadap-generasi-muda"},["strong",{},"Pengaruh terhadap Generasi Muda"]],["p",{},"Generasi muda yang aktif mengikuti Jambore Ranting cenderung memiliki karakter yang lebih positif. Mereka menjadi pribadi yang disiplin, tanggung jawab, peduli terhadap lingkungan, serta mampu berpikir kritis. Dampak ini secara jangka panjang juga membantu menciptakan pemimpin masa depan yang berkualitas untuk bangsa."],["hr",{}],["h2",{"id":""}],["h2",{"id":"faq-tentang-jambore-ranting"},["strong",{},"FAQ tentang Jambore Ranting"]],["p",{},["strong",{},"Apa itu Jambore Ranting?"]," Jambore Ranting adalah pertemuan besar anggota Pramuka di tingkat kecamatan untuk pembinaan karakter, keterampilan, dan solidaritas."],["p",{},["strong",{},"Kapan Jambore Ranting pertama kali diadakan?"]," Pertama kali diadakan pada pertengahan tahun 1960-an di Jawa Tengah."],["p",{},["strong",{},"Siapa tokoh penting dalam Jambore Ranting?"]," Tokoh seperti Sri Sultan Hamengkubuwono IX, Kak Agus Salim, hingga Kak Budi Waseso adalah beberapa di antaranya."],["p",{},["strong",{},"Apa manfaat mengikuti Jambore Ranting?"]," Pembentukan karakter, jiwa nasionalisme, dan kepemimpinan adalah manfaat utamanya."],["p",{},["strong",{},"Apa saja kegiatan di Jambore Ranting?"]," Meliputi kepanduan tradisional, keagamaan, sosial, olahraga, dan permainan tradisional."],["p",{},["strong",{},"Bagaimana masa depan Jambore Ranting di Indonesia?"]," Masa depan menjanjikan dengan inovasi kegiatan berbasis teknologi serta dukungan penuh pemerintah."],["hr",{}],["h2",{"id":"kesimpulan"},["strong",{},"Kesimpulan"]],["p",{},"Jambore Ranting bukan sekadar kegiatan perkemahan biasa, melainkan sebuah warisan budaya edukatif yang terus berkembang. Dengan peran penting dalam pembentukan generasi bangsa, kegiatan ini akan selalu relevan untuk masa depan Indonesia yang lebih baik."]],"toc":{"title":"","searchDepth":2,"depth":2,"links":[{"id":"definisi-dan-tujuan-jambore-ranting","depth":2,"text":"Definisi dan Tujuan Jambore Ranting"},{"id":"sejarah-awal-jambore-ranting-di-indonesia","depth":2,"text":"Sejarah Awal Jambore Ranting di Indonesia","children":[{"id":"latar-belakang-munculnya-jambore-ranting","depth":3,"text":"Latar Belakang Munculnya Jambore Ranting"},{"id":"tahun-pertama-penyelenggaraan","depth":3,"text":"Tahun Pertama Penyelenggaraan"},{"id":"daerah-pertama-yang-mengadakan-jambore-ranting","depth":3,"text":"Daerah Pertama yang Mengadakan Jambore Ranting"}]},{"id":"perkembangan-jambore-ranting-dari-masa-ke-masa","depth":2,"text":"Perkembangan Jambore Ranting dari Masa ke Masa","children":[{"id":"era-1960-an-hingga-1980-an","depth":3,"text":"Era 1960-an hingga 1980-an"},{"id":"transformasi-di-era-reformasi","depth":3,"text":"Transformasi di Era Reformasi"},{"id":"adaptasi-di-era-digital","depth":3,"text":"Adaptasi di Era Digital"}]},{"id":"struktur-organisasi-jambore-ranting","depth":2,"text":"Struktur Organisasi Jambore Ranting","children":[{"id":"tugas-dan-fungsi-panitia-jambore-ranting","depth":3,"text":"Tugas dan Fungsi Panitia Jambore Ranting"},{"id":"peran-gugus-depan-dalam-jambore-ranting","depth":3,"text":"Peran Gugus Depan dalam Jambore Ranting"}]},{"id":"tujuan-dan-manfaat-pelaksanaan-jambore-ranting","depth":2,"text":"Tujuan dan Manfaat Pelaksanaan Jambore Ranting","children":[{"id":"pembentukan-karakter-anggota-pramuka","depth":3,"text":"Pembentukan Karakter Anggota Pramuka"},{"id":"menumbuhkan-jiwa-nasionalisme","depth":3,"text":"Menumbuhkan Jiwa Nasionalisme"},{"id":"meningkatkan-kemandirian-dan-kepemimpinan","depth":3,"text":"Meningkatkan Kemandirian dan Kepemimpinan"}]},{"id":"aktivitas-yang-dilakukan-dalam-jambore-ranting","depth":2,"text":"Aktivitas yang Dilakukan dalam Jambore Ranting","children":[{"id":"kegiatan-kepanduan-tradisional","depth":3,"text":"Kegiatan Kepanduan Tradisional"},{"id":"kegiatan-keagamaan-dan-sosial","depth":3,"text":"Kegiatan Keagamaan dan Sosial"},{"id":"kegiatan-olahraga-dan-permainan-tradisional","depth":3,"text":"Kegiatan Olahraga dan Permainan Tradisional"}]},{"id":"tokoh-penting-dalam-sejarah-jambore-ranting","depth":2,"text":"Tokoh Penting dalam Sejarah Jambore Ranting","children":[{"id":"pelopor-awal-dan-tokoh-inspiratif","depth":3,"text":"Pelopor Awal dan Tokoh Inspiratif"},{"id":"kontribusi-tokoh-tokoh-pramuka-terkenal","depth":3,"text":"Kontribusi Tokoh-tokoh Pramuka Terkenal"}]},{"id":"dampak-jambore-ranting-terhadap-komunitas-lokal","depth":2,"text":"Dampak Jambore Ranting terhadap Komunitas Lokal","children":[{"id":"dampak-sosial-dan-ekonomi","depth":3,"text":"Dampak Sosial dan Ekonomi"},{"id":"pengaruh-terhadap-generasi-muda","depth":3,"text":"Pengaruh terhadap Generasi Muda"}]},{"id":"","depth":2,"text":""},{"id":"faq-tentang-jambore-ranting","depth":2,"text":"FAQ tentang Jambore Ranting"},{"id":"kesimpulan","depth":2,"text":"Kesimpulan"}]}}','2025-07-17T00:00:00.000Z','Jambore Ranting merupakan salah satu kegiatan unggulan dalam Gerakan Pramuka Indonesia yang berfungsi sebagai ajang pembinaan karakter, keterampilan, serta solidaritas bagi anggota muda Pramuka di tingkat kecamatan atau ranting.','md','/artikel/jambore-4.png','{}','true','/artikel/sejarah-jambore-ranting-di-indonesia-10-fakta-menarik','{"title":"Sejarah Jambore Ranting di Indonesia: 10 Fakta Menarik yang Perlu Anda Ketahui","description":"Jambore Ranting merupakan salah satu kegiatan unggulan dalam Gerakan Pramuka Indonesia yang berfungsi sebagai ajang pembinaan karakter, keterampilan, serta solidaritas bagi anggota muda Pramuka di tingkat kecamatan atau ranting."}','artikel/4.sejarah-jambore-ranting-di-indonesia-10-fakta-menarik','["Jambore","Sekolah","Sejarah"]','ABxvKioV6vHbwwQreDwh90bNvApD5e-XNShi1Ojvfj8');
